curvature is exactly
\begin{equation}\label{eq:kappa-def}
  \kappa(\gamma,N) = \lambda_{\min}\!\bigl(R_H^{\circ 2}, R_H\bigr),
  \qquad H = \gamma/2,
\end{equation}
where $R_H$ is the $N \times N$ fBM covariance matrix on $\{1,\ldots,N\}$.
Since $\mathcal{T} = \bigcup_N \mathcal{T}_N$ is a core for $L_\gamma$,
the curvature on the full domain satisfies
$\kappa(\gamma) \leq \lim_{N\to\infty} \kappa(\gamma,N)$.
\end{theorem}

\begin{theorem}\label{thm:cauchy}
At $\gamma = 1$ ($H = 1/2$), the matrix $R_{1/2}^{-1}\,R_{1/2}^{\circ 2}$
is upper triangular with diagonal entries $\{1, 3, 5, \ldots, 2N-1\}$.
Hence $\kappa(1,N) = 1$ for all $N$.
\end{theorem}

\begin{theorem}\label{thm:phase-transition}
\begin{enumerate}[label=(\roman*)]
\item For $\gamma \in (0,1)$: $\kappa(\gamma) := \lim_N \kappa(\gamma,N)$
  exists, is finite, and satisfies $\kappa(\gamma) > 1$.
\item At $\gamma = 1$: $\kappa(1,N) = 1$ for all $N$.
\item For $\gamma \in (1,2)$: $\kappa(\gamma,N) \to -\infty$ as
  $N \to \infty$.
\end{enumerate}
\end{theorem}

\begin{theorem}[Cross-sign vanishing]\label{thm:cross-sign}
For $n,m > 0$:
\begin{equation}\label{eq:cross-sign}
  \Psi_\gamma(n,-m) = \tfrac{1}{2}\bigl(n^\gamma + m^\gamma
  - (n+m)^\gamma\bigr).
\end{equation}
This vanishes identically if and only if $\gamma = 1$:
\begin{enumerate}[label=(\alph*)]
\item At $\gamma = 1$: $\Psi_1(n,-m)
  = \tfrac{1}{2}(n + m - (n+m)) = 0$ for all $n,m > 0$.
\item For $\gamma < 1$: $\Psi_\gamma(n,-m) > 0$
  (subadditivity of $|\cdot|^\gamma$).
\item For $\gamma > 1$: $\Psi_\gamma(n,-m) < 0$
  (superadditivity of $|\cdot|^\gamma$).
\end{enumerate}
\end{theorem}

\begin{corollary}\label{cor:block-diag}
At $\gamma = 1$, the cross-sign block $B = 0$, so the $\Psi_1$
matrix is block-diagonal. Positive and negative frequencies
decouple completely. For real $f$ with $a_{-n} = \bar{a}_n$,
$\kappa_{\mathrm{real}}(1,N) = 1$ for all $N$.
\end{corollary}

\begin{proposition}\label{prop:single-mode}
For $f(x) = \cos(nx + \varphi)$:
\begin{equation}\label{eq:single-mode}
  \frac{\widetilde{\Gamma}_{\gamma,2}(f,f)(x)}
       {\widetilde{\Gamma}_\gamma(f,f)(x)}
  = |n|^\gamma \cdot
  \frac{1 + \alpha_n^2\,\cos(2nx+\theta)}
       {1 + \alpha_n\,\cos(2nx+\theta)},
\end{equation}
where $\alpha_n = 1 - 2^{\gamma-1}$ (independent of $n$)
and $\theta = 2\varphi$. The curvature is
\begin{equation}\label{eq:kappa1}
  \kappa_1(\gamma) = \frac{1 + \alpha^2}{1 + |\alpha|},
  \qquad \alpha = 1 - 2^{\gamma-1}.
\end{equation}
At $\gamma = 1$: $\alpha = 0$, giving $\kappa_1(1) = 1$.
For all $\gamma \neq 1$: $\kappa_1(\gamma) < 1$.
\end{proposition}

\begin{theorem}\label{thm:potential}
For $f(x) = \cos x$ and $V(x) = -\omega^2\cos x$:
\begin{equation}\label{eq:G2-ratio-potential}
  \frac{\Gamma_{L,2}(f,f)(x)}{\Gamma(f,f)(x)}
  = \frac{1 + \alpha^2\cos 2x + \tfrac{\omega^2}{2}(\cos x + \beta\cos 3x)}
         {1 + \alpha\cos 2x},
\end{equation}
where
$\alpha(\gamma) = 1 - 2^{\gamma-1}$ and
$\beta(\gamma) = (2^{\gamma+1} - 3^\gamma - 1)/2$.
\end{theorem}

\begin{proposition}[Refined contraction]\label{prop:refined}
At $\gamma = 1$, decompose $f \in \mathcal{T}_N^+$ along the
eigenbasis $\{\phi_k\}_{k=1}^N$ of $M(1) = R_{1/2}^{-1}\,R_{1/2}^{\circ 2}$.
Then the $k$-th component of the carr\'e du champ contracts at rate
\begin{equation}\label{eq:refined-contraction}
  \Gamma(P_t f, P_t f)_k \leq e^{-2(2k-1)t}\,\Gamma(f,f)_k,
  \qquad k = 1,\ldots,N.
\end{equation}
The total energy satisfies
\begin{equation}\label{eq:total-energy}
  \int_\T \Gamma(P_t f, P_t f)\,d\mu
  \leq \sum_{k=1}^N e^{-2(2k-1)t}\,\mathcal{E}_k(f),
\end{equation}
where $\mathcal{E}_k(f)$ is the energy in the $k$-th eigendirection.
The uniform bound $e^{-2t}\,\mathcal{E}(f)$ is sharp only for
functions concentrated on the first mode ($k=1$).
\end{proposition}

\begin{corollary}[Volume comparison]\label{cor:volume}
The $\Gamma_2$-ellipsoid
$E_2 = \{f : \Gamma_2(f,f) \leq 1\}$ and the $\Gamma$-ellipsoid
$E_1 = \{f : \Gamma(f,f) \leq 1\}$ on $\mathcal{T}_N^+$ satisfy
\begin{equation}\label{eq:volume-ratio}
  \frac{\mathrm{vol}(E_1)}{\mathrm{vol}(E_2)}
  = (\det M)^{1/2} = \bigl((2N-1)!!\bigr)^{1/2}
  = \bigl(\E[X^{2N}]\bigr)^{1/2},
\end{equation}
where $X \sim \mathcal{N}(0,1)$.
At $\gamma = 1$, the $\Gamma_2$-form is $(2N-1)!!^{1/2}$ times
more concentrating than the $\Gamma$-form in $N$-dimensional volume.
\end{corollary}

\begin{theorem}[Hadamard power identity]\label{thm:hierarchy}
For all $\gamma \in (0,2)$, $k \geq 1$, and $\xi,\eta \in \R$:
\begin{equation}\label{eq:Phik-formula}
  \Phi_{\gamma,k}(\xi,\eta) = \bigl[\Psi_\gamma(\xi,\eta)\bigr]^k
  = \bigl[R_{\gamma/2}(|\xi|,|\eta|)\bigr]^k.
\end{equation}
That is, $\Gamma_k$ has Fourier kernel $\Psi_\gamma^k = R_H^{\circ k}$.
\end{theorem}

\begin{corollary}[$k$-th order curvature]\label{cor:kth-curvature}
On $\mathcal{T}_N^+$, the $k$-th order Bakry--\'Emery curvature is
\begin{equation}\label{eq:kappak}
  \kappa^{(k)}(\gamma,N)
  = \lambda_{\min}\!\bigl(R_H^{\circ k},\, R_H^{\circ(k-1)}\bigr),
  \qquad H = \gamma/2, \quad k \geq 2.
\end{equation}
\end{corollary}

\begin{theorem}[Cholesky factorization]\label{thm:cholesky}
Let $M_k$ be the $N \times N$ matrix with entries
$M_k(n,m) = \min(n,m)^k$ for $n,m = 1,\ldots,N$
and $k \geq 1$. Let $L$ be the $N \times N$ unit lower
triangular matrix with $L_{nm} = 1$ for $n \geq m$ and
$L_{nm} = 0$ for $n < m$. Then
\begin{equation}\label{eq:cholesky}
  M_k = L\,D_k\,L^T,
\end{equation}
where $D_k = \mathrm{diag}(d_1^{(k)},\ldots,d_N^{(k)})$ with
\begin{equation}\label{eq:dk}
  d_j^{(k)} = j^k - (j-1)^k = \Delta(j^k),
  \qquad j = 1,\ldots,N,
\end{equation}
and $\Delta$ denotes the backward difference operator
$\Delta f(j) = f(j) - f(j-1)$.
\end{theorem}

\begin{theorem}[Eigenvalues of the $k$-th curvature matrix]
\label{thm:eigenvalues}
At $\gamma = 1$ ($H = 1/2$), for $k \geq 2$, the matrix
\begin{equation}\label{eq:Mk-def}
  \mathcal{M}^{(k)}
  := (M_{k-1})^{-1}\,M_k
  = (R_{1/2}^{\circ(k-1)})^{-1}\,R_{1/2}^{\circ k}
\end{equation}
is upper triangular with eigenvalues
\begin{equation}\label{eq:eigenvalue-formula}
  \kappa_j^{(k)}
  = \frac{d_j^{(k)}}{d_j^{(k-1)}}
  = \frac{j^k - (j-1)^k}{j^{k-1} - (j-1)^{k-1}},
  \qquad j = 1,\ldots,N.
\end{equation}
\end{theorem}

\begin{corollary}[Alternative form]\label{cor:alt-form}
Setting $r_j = (j-1)/j$:
\begin{equation}\label{eq:alt-form}
  \kappa_j^{(k)} = j\;\frac{1 - r_j^k}{1 - r_j^{k-1}},
  \qquad j \geq 1, \quad k \geq 2,
\end{equation}
with $r_1 = 0$ giving $\kappa_1^{(k)} = 1$ for all $k$.
\end{corollary}

\begin{theorem}[Stability across chaos levels]\label{thm:stability}
At $\gamma = 1$, the minimum $k$-th order curvature is
$\kappa^{(k)}(1,N) = \kappa_1^{(k)} = 1$ for all $k \geq 2$
and all $N \geq 1$. The Bakry--\'Emery constant~$1$ is
preserved at every level of the Wiener chaos hierarchy.
\end{theorem}

\begin{theorem}[Factorial interpolation]\label{thm:volume}
The determinant of $\mathcal{M}^{(k)}$ satisfies:
\begin{equation}\label{eq:det-formula}
  \det \mathcal{M}^{(k)}
  = \prod_{j=1}^N \kappa_j^{(k)}
  = N!\;\prod_{j=2}^N \frac{1 - r_j^k}{1 - r_j^{k-1}}.
\end{equation}
In particular:
\begin{enumerate}[label=(\roman*)]
\item At $k = 2$:
  $\det \mathcal{M}^{(2)} = \prod_{j=1}^N (2j-1) = (2N-1)!!
  = \E[X^{2N}]$ for $X \sim \mathcal{N}(0,1)$.
\item As $k \to \infty$:
  $\det \mathcal{M}^{(k)} \to N!$.
\item The sequence $\{\det \mathcal{M}^{(k)}\}_{k \geq 2}$
  is strictly decreasing.
\end{enumerate}
\end{theorem}

\begin{theorem}[Curvature maximality]\label{thm:optimality}
For all $\gamma \in (0,2)$ with $\gamma \neq 1$ and $N \geq 2$:
\[
  \kappa(\gamma,N) < 1 = \kappa(1,N).
\]
\end{theorem}

\begin{lemma}[First-order perturbation]\label{lem:perturbation}
At $H = 1/2$, the derivative of $R_H(n,m)$ with respect to
$H$ is
\begin{equation}\label{eq:dRdH}
  \frac{\partial R_H}{\partial H}\Big|_{H=1/2}(n,m)
  = n\ln n + m\ln m
  - |n-m|\ln|n-m|,
\end{equation}
with the convention $0 \ln 0 = 0$.
\end{lemma}

\begin{theorem}[Higher-order regularization]
\label{thm:regularization}
For all $\gamma \in (0,2)$ and all $N \geq 1$:
\begin{equation}\label{eq:regularization}
  \lim_{k \to \infty} \kappa^{(k)}(\gamma,N) = 1.
\end{equation}
The convergence is exponential in $k$.
\end{theorem}

\begin{proposition}[Subordination map]\label{prop:subordination}
Subordination acts on the duality parameters as:
\begin{equation}\label{eq:sub-map}
  \gamma \mapsto \alpha\gamma,
  \qquad
  H \mapsto \alpha H.
\end{equation}
\end{proposition}

\begin{definition}[Discrete fBM energy space]
\label{def:discrete-energy}
For fBM sampled at $\{1,\ldots,N\}$, define the energy
space $\HH = (\R^N, \langle\cdot,\cdot\rangle_{\HH})$
with inner product
\begin{equation}\label{eq:HH-ip}
  \langle \mathbf{u}, \mathbf{v} \rangle_{\HH}
  := \sum_{n,m=1}^N u_n\,v_m\,R_H(n,m)
  = \mathbf{u}^T R_H\,\mathbf{v}.
\end{equation}
The standard basis vectors $\{e_1,\ldots,e_N\}$
satisfy $\langle e_n, e_m \rangle_{\HH} = R_H(n,m)$.
\end{definition}

\begin{lemma}\label{lem:D-of-BH}
$D_{B^H} B_j^H = e_j$ for $j = 1,\ldots,N$.
\end{lemma}

\begin{definition}[Tensor power]\label{def:tensor}
The $k$-th tensor power $\HH^{\otimes k}$ is
$(\R^N)^{\otimes k} \cong \R^{N^k}$ with inner product
\begin{equation}\label{eq:tensor-ip}
  \langle e_{n_1} \otimes \cdots \otimes e_{n_k},\;
         e_{m_1} \otimes \cdots \otimes e_{m_k}
  \rangle_{\HH^{\otimes k}}
  = \prod_{\ell=1}^k R_H(n_\ell, m_\ell).
\end{equation}
\end{definition}

\begin{definition}[Diagonal tensor lift]\label{def:lift}
The diagonal tensor lift
$\iota_k\colon \R^N \to \HH^{\otimes k}$ is the linear map
\begin{equation}\label{eq:lift}
  \iota_k(\mathbf{v})
  := \sum_{n=1}^N v_n\,e_n^{\otimes k}.
\end{equation}
\end{definition}

\begin{lemma}[Gram matrix of the diagonal lift]
\label{lem:gram}
The Gram matrix of $\{\iota_k(e_1),\ldots,\iota_k(e_N)\}
= \{e_1^{\otimes k},\ldots,e_N^{\otimes k}\}$
in $\HH^{\otimes k}$ is the Hadamard power $R_H^{\circ k}$:
\begin{equation}\label{eq:gram}
  \langle e_n^{\otimes k}, e_m^{\otimes k}
  \rangle_{\HH^{\otimes k}}
  = R_H(n,m)^k
  = R_H^{\circ k}(n,m).
\end{equation}
\end{lemma}

\begin{theorem}[Operator realization]
\label{thm:realization}
For $f = \sum_{n=1}^N a_n\,e^{inx} \in \mathcal{T}_N^+$
with phase-stripped vector
$\mathbf{b}(x) = (a_1 e^{ix}, \ldots, a_N e^{iNx})^T$
and stochastic representative
$\Phi_f(x) := \delta_{B^H}(\mathbf{b}(x))
= \sum_n b_n(x)\,B_n^H$:
\begin{equation}\label{eq:realization}
  \Gamma(f,f)(x)
  = \bigl\|D_{B^H}\Phi_f(x)\bigr\|^2_{\HH}.
\end{equation}
\end{theorem}

\begin{theorem}[Tensor realization]\label{thm:tensor}
For all $\gamma \in (0,2)$, $k \geq 1$, and
$f \in \mathcal{T}_N^+$:
\begin{equation}\label{eq:tensor}
  \Gamma_k(f,f)(x)
  = \bigl\|\iota_k(\mathbf{b}(x))\bigr\|^2_{\HH^{\otimes k}}.
\end{equation}
\end{theorem}

\begin{corollary}[Curvature as contraction ratio]
\label{cor:contraction}
The $k$-th order Bakry--\'Emery curvature is
\begin{equation}\label{eq:kappak}
  \kappa^{(k)}(\gamma,N)
  = \min_{\mathbf{v} \neq 0}
    \frac{\|\iota_k(\mathbf{v})\|^2_{\HH^{\otimes k}}}
         {\|\iota_{k-1}(\mathbf{v})\|^2_{\HH^{\otimes(k-1)}}}
  = \lambda_{\min}(R_H^{\circ k},\, R_H^{\circ(k-1)}).
\end{equation}
\end{corollary}

\begin{lemma}[Orthonormal increments at $H = 1/2$]
\label{lem:increments}
In $\mathcal{H}_{1/2}$, define $\Delta_j := e_j - e_{j-1}$
(with $e_0 = 0$).  Then
$\langle \Delta_i, \Delta_j \rangle_{\mathcal{H}_{1/2}}
= \delta_{ij}$ (Kronecker delta).
\end{lemma}

\begin{theorem}[Increment tensor decomposition]
\label{thm:increment}
Define $\delta_j^{(k)} := e_j^{\otimes k}
- e_{j-1}^{\otimes k}$ for $j = 1,\ldots,N$,
with $e_0^{\otimes k} = 0$.  In
$\mathcal{H}_{1/2}^{\otimes k}$:
\begin{enumerate}[label=\textup{(\roman*)}]
\item \textup{Orthogonality:}
  $\langle \delta_i^{(k)}, \delta_j^{(k)} \rangle = 0$
  for $i \neq j$.
\item \textup{Norm:}
  $\|\delta_j^{(k)}\|^2 = j^k - (j{-}1)^k$.
\item \textup{Expansion:}
  $e_n^{\otimes k} = \sum_{j=1}^n \delta_j^{(k)}$.
\end{enumerate}
\end{theorem}

\begin{corollary}[Cholesky factorization]
\label{cor:cholesky}
The matrix $M_k$ with entries $M_k(n,m) = \min(n,m)^k$
admits the factorization
\begin{equation}\label{eq:cholesky}
  M_k = L\,D_k\,L^T,
\end{equation}
where $L_{nj} = \mathbf{1}_{n \geq j}$ and
$D_k = \mathrm{diag}(j^k - (j{-}1)^k)_{j=1}^N$.
\end{corollary}

\begin{theorem}[Eigenvalues as increment-tensor ratios]
\label{thm:eigenvalues}
At $\gamma = 1$, for $k \geq 2$, the $k$-th curvature
matrix
\[
  \mathcal{M}^{(k)}
  := (M_{k-1})^{-1}\,M_k
  = (R_{1/2}^{\circ(k-1)})^{-1}\,R_{1/2}^{\circ k}
\]
is upper triangular with eigenvalues
\begin{equation}\label{eq:eigenvalue-formula}
  \kappa_j^{(k)}
  = \frac{\|\delta_j^{(k)}\|^2}{\|\delta_j^{(k-1)}\|^2}
  = \frac{j^k - (j-1)^k}{j^{k-1} - (j-1)^{k-1}},
  \qquad j = 1,\ldots,N.
\end{equation}
\end{theorem}

\begin{corollary}[Curvature stability]
\label{cor:stability}
$\kappa^{(k)}(1,N) = \kappa_1^{(k)} = 1$ for all
$k \geq 2$ and all $N \geq 1$.
\end{corollary}

\begin{theorem}[Factorial interpolation]
\label{thm:volume}
The determinant of the $k$-th curvature matrix satisfies:
\begin{equation}\label{eq:det-formula}
  \det \mathcal{M}^{(k)}
  = \prod_{j=1}^N \kappa_j^{(k)}
  = \prod_{j=1}^N
    \frac{\|\delta_j^{(k)}\|^2}{\|\delta_j^{(k-1)}\|^2}.
\end{equation}
In particular:
\begin{enumerate}[label=\textup{(\roman*)}]
\item At $k = 2$:
  $\det \mathcal{M}^{(2)} = \prod(2j-1) = (2N{-}1)!!
  = \E[X^{2N}]$ for $X \sim \mathcal{N}(0,1)$.
\item As $k \to \infty$:
  $\det \mathcal{M}^{(k)} \to N!$.
\item The sequence is strictly decreasing in $k$.
\end{enumerate}
\end{theorem}

\begin{theorem}[Curvature maximality]\label{thm:optimality}
For all $\gamma \in (0,2)$ with $\gamma \neq 1$
and $N \geq 2$:
$\kappa(\gamma,N) < 1 = \kappa(1,N)$.
\end{theorem}

\begin{definition}[fBM correlation matrix]\label{def:corr}
For $H \in (0,1)$ and $n,m \in \{1,\ldots,N\}$, define
\begin{equation}\label{eq:rho}
  \rho_{nm}
  := \frac{R_H(n,m)}{n^H\,m^H}
  = \frac{n^{2H} + m^{2H} - |n-m|^{2H}}{2\,n^H\,m^H},
\end{equation}
and set $\Delta := \mathrm{diag}(1^H, 2^H, \ldots, N^H)$.
Then $R_H = \Delta\,\rho\,\Delta$ and
$R_H^{\circ k} = \Delta^k\,\rho^{\circ k}\,\Delta^k$.
\end{definition}

\begin{lemma}[Reduced eigenvalue problem]
\label{lem:substitution}
The $k$-th order curvature satisfies
\begin{equation}\label{eq:reduced}
  \kappa^{(k)}(\gamma,N)
  = \min_{w \neq 0}
    \frac{w^T\,\Delta\,\rho^{\circ k}\,\Delta\,w}
         {w^T\,\rho^{\circ(k-1)}\,w}.
\end{equation}
\end{lemma}

\begin{definition}[Curvature flow]\label{def:flow}
The subordination flow is
$\mathcal{S}_\alpha(\gamma) = \alpha\gamma$,
with orbit $\gamma_n = \alpha^n\gamma_0$ and
curvatures $\kappa_n := \kappa(\gamma_n)$.
\end{definition}

\begin{definition}[$k$-th energy functional]
\label{def:energy-k}
For $f \in \mathcal{T}_N^+$ and $k \geq 1$:
\begin{equation}\label{eq:Ek}
  \mathcal{E}_k(f)
  := \int_\T \Gamma_k(f,f)\,d\mu
  = \sum_{n=1}^N |a_n|^2\,n^{2Hk},
\end{equation}
where the second equality follows from orthogonality of
$e^{i(m-n)x}$ under $\mu = dx/(2\pi)$.
\end{definition}

\begin{lemma}[Energy dissipation identity]
\label{lem:dissipation}
For $k \geq 1$ and $f \in \mathcal{T}_N^+$:
\begin{equation}\label{eq:dissipation}
  \frac{d}{dt}\,\mathcal{E}_k(P_t f)
  = -2\,\mathcal{E}_{k+1}(P_t f).
\end{equation}
Each energy level is dissipated by the next.
\end{lemma}

\begin{theorem}[Semigroup energy decay hierarchy]
\label{thm:decay}
For $k \geq 1$ and $f \in \mathcal{T}_N^+$:
\begin{equation}\label{eq:decay}
  \mathcal{E}_k(P_t f)
  \;\leq\; e^{-2\kappa^{(k+1)}(\gamma,N)\,t}\,
  \mathcal{E}_k(f).
\end{equation}
The $k$-th energy decays exponentially at rate
$2\kappa^{(k+1)}$.
\end{theorem}

\begin{corollary}[Universal high-chaos decay rate]
\label{cor:universality}
For all $\gamma \in (0,2)$ and $\varepsilon > 0$,
there exists $k_0 = k_0(\gamma, N, \varepsilon)$ such that
for all $k \geq k_0$ and all $f \in \mathcal{T}_N^+$:
\begin{equation}\label{eq:universality}
  \mathcal{E}_k(P_t f)
  \;\leq\; e^{-2(1-\varepsilon)\,t}\,\mathcal{E}_k(f).
\end{equation}
That is, the decay rate at high energy levels
approaches $e^{-2t}$---the Gaussian rate---for all
stable generators, regardless of $\gamma$.
\end{corollary}

\begin{proposition}[Mode-resolved decay]
\label{prop:mode-decay}
At $\gamma = 1$, for each mode $f = e^{inx}$
($n = 1,\ldots,N$):
\begin{equation}\label{eq:mode-decay}
  \frac{\mathcal{E}_{k+1}(P_t e^{inx})}
       {\mathcal{E}_k(P_t e^{inx})}
  = n \qquad \text{for all } t \geq 0.
\end{equation}
More generally, for any $f \in \mathcal{T}_N^+$:
\begin{equation}\label{eq:sandwich}
  1\;\leq\;
  \frac{\mathcal{E}_{k+1}(P_t f)}{\mathcal{E}_k(P_t f)}
  \;\leq\; N,
\end{equation}
and both bounds are attained (by $e^{ix}$ and $e^{iNx}$
respectively).
\end{proposition}

\begin{definition}[Discrete fBM energy space]
\label{def:discrete-energy}
For fBM sampled at $\{1,\ldots,N\}$, define the energy
space $\HH = (\R^N, \langle\cdot,\cdot\rangle_{\HH})$
with inner product
\begin{equation}\label{eq:HH-ip}
  \langle \mathbf{u}, \mathbf{v} \rangle_{\HH}
  := \sum_{n,m=1}^N u_n\,v_m\,R_H(n,m)
  = \mathbf{u}^T R_H\,\mathbf{v}.
\end{equation}
The standard basis vectors $\{e_1,\ldots,e_N\}$
satisfy $\langle e_n, e_m \rangle_{\HH} = R_H(n,m)$.
\end{definition}

\begin{lemma}\label{lem:D-of-BH}
$D_{B^H} B_j^H = e_j$ for $j = 1,\ldots,N$.
\end{lemma}

\begin{definition}[Tensor power]\label{def:tensor}
The $k$-th tensor power $\HH^{\otimes k}$ is
$(\R^N)^{\otimes k} \cong \R^{N^k}$ with inner product
\begin{equation}\label{eq:tensor-ip}
  \langle e_{n_1} \otimes \cdots \otimes e_{n_k},\;
         e_{m_1} \otimes \cdots \otimes e_{m_k}
  \rangle_{\HH^{\otimes k}}
  = \prod_{\ell=1}^k R_H(n_\ell, m_\ell).
\end{equation}
\end{definition}

\begin{definition}[Diagonal tensor lift]\label{def:lift}
The diagonal tensor lift
$\iota_k\colon \R^N \to \HH^{\otimes k}$ is the linear map
\begin{equation}\label{eq:lift}
  \iota_k(\mathbf{v})
  := \sum_{n=1}^N v_n\,e_n^{\otimes k}.
\end{equation}
\end{definition}

\begin{lemma}[Gram matrix of the diagonal lift]
\label{lem:gram}
The Gram matrix of $\{\iota_k(e_1),\ldots,\iota_k(e_N)\}
= \{e_1^{\otimes k},\ldots,e_N^{\otimes k}\}$
in $\HH^{\otimes k}$ is the Hadamard power $R_H^{\circ k}$:
\begin{equation}\label{eq:gram}
  \langle e_n^{\otimes k}, e_m^{\otimes k}
  \rangle_{\HH^{\otimes k}}
  = R_H(n,m)^k
  = R_H^{\circ k}(n,m).
\end{equation}
\end{lemma}

\begin{theorem}[Operator realization]
\label{thm:realization}
For $f = \sum_{n=1}^N a_n\,e^{inx} \in \mathcal{T}_N^+$
with phase-stripped vector
$\mathbf{b}(x) = (a_1 e^{ix}, \ldots, a_N e^{iNx})^T$
and stochastic representative
$\Phi_f(x) := \delta_{B^H}(\mathbf{b}(x))
= \sum_n b_n(x)\,B_n^H$:
\begin{equation}\label{eq:realization}
  \Gamma(f,f)(x)
  = \bigl\|D_{B^H}\Phi_f(x)\bigr\|^2_{\HH}.
\end{equation}
\end{theorem}

\begin{theorem}[Tensor realization]\label{thm:tensor}
For all $\gamma \in (0,2)$, $k \geq 1$, and
$f \in \mathcal{T}_N^+$:
\begin{equation}\label{eq:tensor}
  \Gamma_k(f,f)(x)
  = \bigl\|\iota_k(\mathbf{b}(x))\bigr\|^2_{\HH^{\otimes k}}.
\end{equation}
\end{theorem}

\begin{corollary}[Curvature as contraction ratio]
\label{cor:contraction}
The $k$-th order Bakry--\'Emery curvature is
\begin{equation}\label{eq:kappak}
  \kappa^{(k)}(\gamma,N)
  = \min_{\mathbf{v} \neq 0}
    \frac{\|\iota_k(\mathbf{v})\|^2_{\HH^{\otimes k}}}
         {\|\iota_{k-1}(\mathbf{v})\|^2_{\HH^{\otimes(k-1)}}}
  = \lambda_{\min}(R_H^{\circ k},\, R_H^{\circ(k-1)}).
\end{equation}
\end{corollary}

\begin{lemma}[Orthonormal increments at $H = 1/2$]
\label{lem:increments}
In $\mathcal{H}_{1/2}$, define $\Delta_j := e_j - e_{j-1}$
(with $e_0 = 0$).  Then
$\langle \Delta_i, \Delta_j \rangle_{\mathcal{H}_{1/2}}
= \delta_{ij}$ (Kronecker delta).
\end{lemma}

\begin{theorem}[Increment tensor decomposition]
\label{thm:increment}
Define $\delta_j^{(k)} := e_j^{\otimes k}
- e_{j-1}^{\otimes k}$ for $j = 1,\ldots,N$,
with $e_0^{\otimes k} = 0$.  In
$\mathcal{H}_{1/2}^{\otimes k}$:
\begin{enumerate}[label=\textup{(\roman*)}]
\item \textup{Orthogonality:}
  $\langle \delta_i^{(k)}, \delta_j^{(k)} \rangle = 0$
  for $i \neq j$.
\item \textup{Norm:}
  $\|\delta_j^{(k)}\|^2 = j^k - (j{-}1)^k$.
\item \textup{Expansion:}
  $e_n^{\otimes k} = \sum_{j=1}^n \delta_j^{(k)}$.
\end{enumerate}
\end{theorem}

\begin{corollary}[Cholesky factorization]
\label{cor:cholesky}
The matrix $M_k$ with entries $M_k(n,m) = \min(n,m)^k$
admits the factorization
\begin{equation}\label{eq:cholesky}
  M_k = L\,D_k\,L^T,
\end{equation}
where $L_{nj} = \mathbf{1}_{n \geq j}$ and
$D_k = \mathrm{diag}(j^k - (j{-}1)^k)_{j=1}^N$.
\end{corollary}

\begin{theorem}[Eigenvalues as increment-tensor ratios]
\label{thm:eigenvalues}
At $\gamma = 1$, for $k \geq 2$, the $k$-th curvature
matrix
\[
  \mathcal{M}^{(k)}
  := (M_{k-1})^{-1}\,M_k
  = (R_{1/2}^{\circ(k-1)})^{-1}\,R_{1/2}^{\circ k}
\]
is upper triangular with eigenvalues
\begin{equation}\label{eq:eigenvalue-formula}
  \kappa_j^{(k)}
  = \frac{\|\delta_j^{(k)}\|^2}{\|\delta_j^{(k-1)}\|^2}
  = \frac{j^k - (j-1)^k}{j^{k-1} - (j-1)^{k-1}},
  \qquad j = 1,\ldots,N.
\end{equation}
\end{theorem}

\begin{corollary}[Curvature stability]
\label{cor:stability}
$\kappa^{(k)}(1,N) = \kappa_1^{(k)} = 1$ for all
$k \geq 2$ and all $N \geq 1$.
\end{corollary}

\begin{theorem}[Factorial interpolation]
\label{thm:volume}
The determinant of the $k$-th curvature matrix satisfies:
\begin{equation}\label{eq:det-formula}
  \det \mathcal{M}^{(k)}
  = \prod_{j=1}^N \kappa_j^{(k)}
  = \prod_{j=1}^N
    \frac{\|\delta_j^{(k)}\|^2}{\|\delta_j^{(k-1)}\|^2}.
\end{equation}
In particular:
\begin{enumerate}[label=\textup{(\roman*)}]
\item At $k = 2$:
  $\det \mathcal{M}^{(2)} = \prod(2j-1) = (2N{-}1)!!
  = \E[X^{2N}]$ for $X \sim \mathcal{N}(0,1)$.
\item As $k \to \infty$:
  $\det \mathcal{M}^{(k)} \to N!$.
\item The sequence is strictly decreasing in $k$.
\end{enumerate}
\end{theorem}

\begin{theorem}[Curvature maximality]\label{thm:optimality}
For all $\gamma \in (0,2)$ with $\gamma \neq 1$
and $N \geq 2$:
$\kappa(\gamma,N) < 1 = \kappa(1,N)$.
\end{theorem}

\begin{definition}[fBM correlation matrix]\label{def:corr}
For $H \in (0,1)$ and $n,m \in \{1,\ldots,N\}$, define
\begin{equation}\label{eq:rho}
  \rho_{nm}
  := \frac{R_H(n,m)}{n^H\,m^H}
  = \frac{n^{2H} + m^{2H} - |n-m|^{2H}}{2\,n^H\,m^H},
\end{equation}
and set $\Delta := \mathrm{diag}(1^H, 2^H, \ldots, N^H)$.
Then $R_H = \Delta\,\rho\,\Delta$ and
$R_H^{\circ k} = \Delta^k\,\rho^{\circ k}\,\Delta^k$.
\end{definition}

\begin{lemma}[Reduced eigenvalue problem]
\label{lem:substitution}
The $k$-th order curvature satisfies
\begin{equation}\label{eq:reduced}
  \kappa^{(k)}(\gamma,N)
  = \min_{w \neq 0}
    \frac{w^T\,\Delta\,\rho^{\circ k}\,\Delta\,w}
         {w^T\,\rho^{\circ(k-1)}\,w}.
\end{equation}
\end{lemma}

\begin{definition}[Curvature flow]\label{def:flow}
The subordination flow is
$\mathcal{S}_\alpha(\gamma) = \alpha\gamma$,
with orbit $\gamma_n = \alpha^n\gamma_0$ and
curvatures $\kappa_n := \kappa(\gamma_n)$.
\end{definition}

\begin{definition}\label{def:cdc}
The sesquilinear carr\'e du champ of $L_\gamma$ is
\begin{equation}\label{eq:cdc}
  \widetilde{\Gamma}_\gamma(f,g)(x)
  := \frac{1}{2} \int_{\R \setminus \{0\}}
  \bigl[f(x+z) - f(x)\bigr]\,
  \overline{\bigl[g(x+z) - g(x)\bigr]}\;
  \nu_\gamma(dz).
\end{equation}
On Fourier modes:
\begin{equation}\label{eq:psi-kernel}
  \widetilde{\Gamma}_\gamma(e^{i\xi\cdot}, e^{i\eta\cdot})(x)
  = e^{i(\xi-\eta)x}\,\Psi_\gamma(\xi,\eta),
\end{equation}
where $\Psi_\gamma(\xi,\eta)
= \tfrac{1}{2}(|\xi|^\gamma + |\eta|^\gamma - |\xi-\eta|^\gamma)$.
Exponentials $e^{i\xi\,\cdot}$ lie in the extended Dirichlet space
of~$L_\gamma$ on $\T$ for all $\gamma \in (0,2)$; see
\cite{BoettcherSchillingWang2013}, \S4.7, for the general framework
of carr\'e du champ for L\'evy-type operators.
\end{definition}

\begin{definition}\label{def:gamma2}
The iterated carr\'e du champ is
\begin{equation}\label{eq:gamma2-def}
  \widetilde{\Gamma}_{\gamma,2}(f,f)
  := \frac{1}{2}\Bigl[
    L_\gamma\bigl(\widetilde{\Gamma}_\gamma(f,f)\bigr)
    - 2\,\widetilde{\Gamma}_\gamma(f, L_\gamma f)
  \Bigr].
\end{equation}
The Bakry--\'Emery condition is
$\widetilde{\Gamma}_{\gamma,2}(f,f)(x) \geq \kappa\,
\widetilde{\Gamma}_\gamma(f,f)(x)$.
\end{definition}

\begin{theorem}[Stable--fBM correspondence]\label{thm:duality}
For $\gamma \in (0,2)$ and all $\xi, \eta \in \R$:
\begin{equation}\label{eq:duality}
  \Psi_\gamma(\xi,\eta)
  = \tfrac{1}{2}\bigl(|\xi|^\gamma + |\eta|^\gamma
  - |\xi - \eta|^\gamma\bigr)
  = R_{\gamma/2}(|\xi|, |\eta|).
\end{equation}
The carr\'e du champ of the $\gamma$-stable generator, evaluated
on Fourier modes, is the covariance of fBM with $H = \gamma/2$.
\end{theorem}

\begin{theorem}[Hadamard square]\label{thm:gamma2-kernel}
For $\gamma \in (0,2)$ and $\xi,\eta \in \R$:
\begin{equation}\label{eq:Phi-formula}
  \Phi_{\gamma,2}(\xi,\eta) = \bigl[\Psi_\gamma(\xi,\eta)\bigr]^2
  = \bigl[R_{\gamma/2}(|\xi|,|\eta|)\bigr]^2.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:curvature}
On the space $\mathcal{T}_N^+$ of positive-frequency trigonometric
polynomials $f = \sum_{n=1}^N a_n\,e^{inx}$, the Bakry--\'Emery
curvature is exactly
\begin{equation}\label{eq:kappa-def}
  \kappa(\gamma,N) = \lambda_{\min}\!\bigl(R_H^{\circ 2}, R_H\bigr),
  \qquad H = \gamma/2,
\end{equation}
where $R_H$ is the $N \times N$ fBM covariance matrix on $\{1,\ldots,N\}$.
Since $\mathcal{T} = \bigcup_N \mathcal{T}_N$ is a core for $L_\gamma$,
the curvature on the full domain satisfies
$\kappa(\gamma) \leq \lim_{N\to\infty} \kappa(\gamma,N)$.
\end{theorem}

\begin{theorem}\label{thm:cauchy}
At $\gamma = 1$ ($H = 1/2$), the matrix $R_{1/2}^{-1}\,R_{1/2}^{\circ 2}$
is upper triangular with diagonal entries $\{1, 3, 5, \ldots, 2N-1\}$.
Hence $\kappa(1,N) = 1$ for all $N$.
\end{theorem}

\begin{theorem}\label{thm:phase-transition}
\begin{enumerate}[label=(\roman*)]
\item For $\gamma \in (0,1)$: $\kappa(\gamma) := \lim_N \kappa(\gamma,N)$
  exists, is finite, and satisfies $\kappa(\gamma) > 1$.
\item At $\gamma = 1$: $\kappa(1,N) = 1$ for all $N$.
\item For $\gamma \in (1,2)$: $\kappa(\gamma,N) \to -\infty$ as
  $N \to \infty$.
\end{enumerate}
\end{theorem}

\begin{theorem}[Cross-sign vanishing]\label{thm:cross-sign}
For $n,m > 0$:
\begin{equation}\label{eq:cross-sign}
  \Psi_\gamma(n,-m) = \tfrac{1}{2}\bigl(n^\gamma + m^\gamma
  - (n+m)^\gamma\bigr).
\end{equation}
This vanishes identically if and only if $\gamma = 1$:
\begin{enumerate}[label=(\alph*)]
\item At $\gamma = 1$: $\Psi_1(n,-m)
  = \tfrac{1}{2}(n + m - (n+m)) = 0$ for all $n,m > 0$.
\item For $\gamma < 1$: $\Psi_\gamma(n,-m) > 0$
  (subadditivity of $|\cdot|^\gamma$).
\item For $\gamma > 1$: $\Psi_\gamma(n,-m) < 0$
  (superadditivity of $|\cdot|^\gamma$).
\end{enumerate}
\end{theorem}

\begin{corollary}\label{cor:block-diag}
At $\gamma = 1$, the cross-sign block $B = 0$, so the $\Psi_1$
matrix is block-diagonal. Positive and negative frequencies
decouple completely. For real $f$ with $a_{-n} = \bar{a}_n$,
$\kappa_{\mathrm{real}}(1,N) = 1$ for all $N$.
\end{corollary}

\begin{proposition}\label{prop:single-mode}
For $f(x) = \cos(nx + \varphi)$:
\begin{equation}\label{eq:single-mode}
  \frac{\widetilde{\Gamma}_{\gamma,2}(f,f)(x)}
       {\widetilde{\Gamma}_\gamma(f,f)(x)}
  = |n|^\gamma \cdot
  \frac{1 + \alpha_n^2\,\cos(2nx+\theta)}
       {1 + \alpha_n\,\cos(2nx+\theta)},
\end{equation}
where $\alpha_n = 1 - 2^{\gamma-1}$ (independent of $n$)
and $\theta = 2\varphi$. The curvature is
\begin{equation}\label{eq:kappa1}
  \kappa_1(\gamma) = \frac{1 + \alpha^2}{1 + |\alpha|},
  \qquad \alpha = 1 - 2^{\gamma-1}.
\end{equation}
At $\gamma = 1$: $\alpha = 0$, giving $\kappa_1(1) = 1$.
For all $\gamma \neq 1$: $\kappa_1(\gamma) < 1$.
\end{proposition}

\begin{theorem}\label{thm:potential}
For $f(x) = \cos x$ and $V(x) = -\omega^2\cos x$:
\begin{equation}\label{eq:G2-ratio-potential}
  \frac{\Gamma_{L,2}(f,f)(x)}{\Gamma(f,f)(x)}
  = \frac{1 + \alpha^2\cos 2x + \tfrac{\omega^2}{2}(\cos x + \beta\cos 3x)}
         {1 + \alpha\cos 2x},
\end{equation}
where
$\alpha(\gamma) = 1 - 2^{\gamma-1}$ and
$\beta(\gamma) = (2^{\gamma+1} - 3^\gamma - 1)/2$.
\end{theorem}

\begin{proposition}[Refined contraction]\label{prop:refined}
At $\gamma = 1$, decompose $f \in \mathcal{T}_N^+$ along the
eigenbasis $\{\phi_k\}_{k=1}^N$ of $M(1) = R_{1/2}^{-1}\,R_{1/2}^{\circ 2}$.
Then the $k$-th component of the carr\'e du champ contracts at rate
\begin{equation}\label{eq:refined-contraction}
  \Gamma(P_t f, P_t f)_k \leq e^{-2(2k-1)t}\,\Gamma(f,f)_k,
  \qquad k = 1,\ldots,N.
\end{equation}
The total energy satisfies
\begin{equation}\label{eq:total-energy}
  \int_\T \Gamma(P_t f, P_t f)\,d\mu
  \leq \sum_{k=1}^N e^{-2(2k-1)t}\,\mathcal{E}_k(f),
\end{equation}
where $\mathcal{E}_k(f)$ is the energy in the $k$-th eigendirection.
The uniform bound $e^{-2t}\,\mathcal{E}(f)$ is sharp only for
functions concentrated on the first mode ($k=1$).
\end{proposition}

\begin{corollary}[Volume comparison]\label{cor:volume}
The $\Gamma_2$-ellipsoid
$E_2 = \{f : \Gamma_2(f,f) \leq 1\}$ and the $\Gamma$-ellipsoid
$E_1 = \{f : \Gamma(f,f) \leq 1\}$ on $\mathcal{T}_N^+$ satisfy
\begin{equation}\label{eq:volume-ratio}
  \frac{\mathrm{vol}(E_1)}{\mathrm{vol}(E_2)}
  = (\det M)^{1/2} = \bigl((2N-1)!!\bigr)^{1/2}
  = \bigl(\E[X^{2N}]\bigr)^{1/2},
\end{equation}
where $X \sim \mathcal{N}(0,1)$.
At $\gamma = 1$, the $\Gamma_2$-form is $(2N-1)!!^{1/2}$ times
more concentrating than the $\Gamma$-form in $N$-dimensional volume.
\end{corollary}

