  = |n|^\gamma \cdot
  \frac{1 + \alpha_n^2\,\cos(2nx+\theta)}
       {1 + \alpha_n\,\cos(2nx+\theta)},
\end{equation}
where $\alpha_n = 1 - 2^{\gamma-1}$ (independent of $n$)
and $\theta = 2\varphi$. The curvature is
\begin{equation}\label{eq:kappa1}
  \kappa_1(\gamma) =
  \begin{cases}
    \displaystyle\frac{1 + \alpha^2}{1 + \alpha}
    & \text{if } \gamma \leq 1 \;(\alpha \geq 0), \\[6pt]
    1 + \alpha = 2 - 2^{\gamma-1}
    & \text{if } \gamma > 1 \;(\alpha < 0),
  \end{cases}
  \qquad \alpha = 1 - 2^{\gamma-1}.
\end{equation}
At $\gamma = 1$: $\alpha = 0$, giving $\kappa_1(1) = 1$.
For all $\gamma \neq 1$: $\kappa_1(\gamma) < 1$.
\end{proposition}

\begin{proposition}\label{thm:potential-single}
For $f(x) = \cos x$ and $V(x) = -\omega^2\cos x$:
\begin{equation}\label{eq:G2-ratio-potential}
  \frac{\Gamma_{L,2}(f,f)(x)}{\Gamma(f,f)(x)}
  = \frac{1 + \alpha^2\cos 2x + \tfrac{\omega^2}{2}(\cos x + \beta\cos 3x)}
         {1 + \alpha\cos 2x},
\end{equation}
where
$\alpha(\gamma) = 1 - 2^{\gamma-1}$ and
$\beta(\gamma) = (2^{\gamma+1} - 3^\gamma - 1)/2$.
At $\gamma = 1$: $\alpha = \beta = 0$, giving
$\Gamma_{L,2}/\Gamma = 1 + \frac{\omega^2}{2}\cos x$
with minimum $1 - \omega^2/2$ at $x = \pi$.
\end{proposition}

\begin{proposition}[Refined contraction]\label{prop:refined}
At $\gamma = 1$, decompose $f \in \mathcal{T}_N^+$ along the
eigenbasis $\{\phi_k\}_{k=1}^N$ of $M(1) = R_{1/2}^{-1}\,R_{1/2}^{\circ 2}$.
Then the $k$-th component of the carr\'e du champ contracts at rate
\begin{equation}\label{eq:refined-contraction}
  \Gamma(P_t f, P_t f)_k \leq e^{-2(2k-1)t}\,\Gamma(f,f)_k,
  \qquad k = 1,\ldots,N.
\end{equation}
The total energy satisfies
\begin{equation}\label{eq:total-energy}
  \int_\T \Gamma(P_t f, P_t f)\,d\mu
  \leq \sum_{k=1}^N e^{-2(2k-1)t}\,\mathcal{E}_k(f),
\end{equation}
where $\mathcal{E}_k(f)$ is the energy in the $k$-th eigendirection.
The uniform bound $e^{-2t}\,\mathcal{E}(f)$ is sharp only for
functions concentrated on the first mode ($k=1$).
\end{proposition}

\begin{corollary}[Volume comparison]\label{cor:volume}
The $\Gamma_2$-ellipsoid
$E_2 = \{f : \Gamma_2(f,f) \leq 1\}$ and the $\Gamma$-ellipsoid
$E_1 = \{f : \Gamma(f,f) \leq 1\}$ on $\mathcal{T}_N^+$ satisfy
\begin{equation}\label{eq:volume-ratio}
  \frac{\mathrm{vol}(E_1)}{\mathrm{vol}(E_2)}
  = (\det M)^{1/2} = \bigl((2N-1)!!\bigr)^{1/2}
  = \bigl(\E[X^{2N}]\bigr)^{1/2},
\end{equation}
where $X \sim \mathcal{N}(0,1)$.
At $\gamma = 1$, the $\Gamma_2$-form is $(2N-1)!!^{1/2}$ times
more concentrating than the $\Gamma$-form in $N$-dimensional volume.
\end{corollary}

\begin{definition}\label{def:cdc}
The sesquilinear carr\'e du champ of $L_\gamma$ is
\begin{equation}\label{eq:cdc}
  \widetilde{\Gamma}_\gamma(f,g)(x)
  := \frac{1}{2} \int_{\R \setminus \{0\}}
  \bigl[f(x+z) - f(x)\bigr]\,
  \overline{\bigl[g(x+z) - g(x)\bigr]}\;
  \nu_\gamma(dz).
\end{equation}
On Fourier modes:
\begin{equation}\label{eq:psi-kernel}
  \widetilde{\Gamma}_\gamma(e^{i\xi\cdot}, e^{i\eta\cdot})(x)
  = e^{i(\xi-\eta)x}\,\Psi_\gamma(\xi,\eta),
\end{equation}
where $\Psi_\gamma(\xi,\eta)
= \tfrac{1}{2}(|\xi|^\gamma + |\eta|^\gamma - |\xi-\eta|^\gamma)$.
Exponentials $e^{i\xi\,\cdot}$ lie in the extended Dirichlet space
of~$L_\gamma$ on $\T$ for all $\gamma \in (0,2)$; see
\cite{BoettcherSchillingWang2013}, \S4.7, for the general framework
of carr\'e du champ for L\'evy-type operators.
\end{definition}

\begin{definition}\label{def:gamma2}
The iterated carr\'e du champ is
\begin{equation}\label{eq:gamma2-def}
  \widetilde{\Gamma}_{\gamma,2}(f,f)
  := \frac{1}{2}\Bigl[
    L_\gamma\bigl(\widetilde{\Gamma}_\gamma(f,f)\bigr)
    - 2\,\widetilde{\Gamma}_\gamma(f, L_\gamma f)
  \Bigr].
\end{equation}
The Bakry--\'Emery condition is
$\widetilde{\Gamma}_{\gamma,2}(f,f)(x) \geq \kappa\,
\widetilde{\Gamma}_\gamma(f,f)(x)$.
\end{definition}

\begin{theorem}[Stable--fBM correspondence]\label{thm:duality}
For $\gamma \in (0,2)$ and all $\xi, \eta \in \R$:
\begin{equation}\label{eq:duality}
  \Psi_\gamma(\xi,\eta)
  = \tfrac{1}{2}\bigl(|\xi|^\gamma + |\eta|^\gamma
  - |\xi - \eta|^\gamma\bigr)
  = R_{\gamma/2}(|\xi|, |\eta|).
\end{equation}
The carr\'e du champ of the $\gamma$-stable generator, evaluated
on Fourier modes, is the covariance of fBM with $H = \gamma/2$.
\end{theorem}

\begin{theorem}[Hadamard square]\label{thm:gamma2-kernel}
For $\gamma \in (0,2)$ and $\xi,\eta \in \R$:
\begin{equation}\label{eq:Phi-formula}
  \Phi_{\gamma,2}(\xi,\eta) = \bigl[\Psi_\gamma(\xi,\eta)\bigr]^2
  = \bigl[R_{\gamma/2}(|\xi|,|\eta|)\bigr]^2.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:curvature}
On the space $\mathcal{T}_N^+$ of positive-frequency trigonometric
polynomials $f = \sum_{n=1}^N a_n\,e^{inx}$, the Bakry--\'Emery
curvature is exactly
\begin{equation}\label{eq:kappa-def}
  \kappa(\gamma,N) = \lambda_{\min}\!\bigl(R_H^{\circ 2}, R_H\bigr),
  \qquad H = \gamma/2,
\end{equation}
where $R_H$ is the $N \times N$ fBM covariance matrix on $\{1,\ldots,N\}$.
Since $\mathcal{T} = \bigcup_N \mathcal{T}_N$ is a core for $L_\gamma$,
the curvature on the full domain satisfies
$\kappa(\gamma) \leq \lim_{N\to\infty} \kappa(\gamma,N)$.
\end{theorem}

\begin{theorem}\label{thm:cauchy}
At $\gamma = 1$ ($H = 1/2$), the matrix $R_{1/2}^{-1}\,R_{1/2}^{\circ 2}$
is upper triangular with diagonal entries $\{1, 3, 5, \ldots, 2N-1\}$.
Hence $\kappa(1,N) = 1$ for all $N$.
\end{theorem}

\begin{theorem}\label{thm:phase-transition}
\begin{enumerate}[label=(\roman*)]
\item For $\gamma \in (0,1)$: $\kappa(\gamma) := \lim_N \kappa(\gamma,N)$
  exists, is finite, and satisfies $\kappa(\gamma) > 1$.
\item At $\gamma = 1$: $\kappa(1,N) = 1$ for all $N$.
\item For $\gamma \in (1,2)$: $\kappa(\gamma,N) \to -\infty$ as
  $N \to \infty$.
\end{enumerate}
\end{theorem}

\begin{theorem}[Cross-sign vanishing]\label{thm:cross-sign}
For $n,m > 0$:
\begin{equation}\label{eq:cross-sign}
  \Psi_\gamma(n,-m) = \tfrac{1}{2}\bigl(n^\gamma + m^\gamma
  - (n+m)^\gamma\bigr).
\end{equation}
This vanishes identically if and only if $\gamma = 1$:
\begin{enumerate}[label=(\alph*)]
\item At $\gamma = 1$: $\Psi_1(n,-m)
  = \tfrac{1}{2}(n + m - (n+m)) = 0$ for all $n,m > 0$.
\item For $\gamma < 1$: $\Psi_\gamma(n,-m) > 0$
  (subadditivity of $|\cdot|^\gamma$).
\item For $\gamma > 1$: $\Psi_\gamma(n,-m) < 0$
  (superadditivity of $|\cdot|^\gamma$).
\end{enumerate}
\end{theorem}

\begin{corollary}\label{cor:block-diag}
At $\gamma = 1$, the cross-sign block $B = 0$, so the $\Psi_1$
matrix is block-diagonal. Positive and negative frequencies
decouple completely. For real $f$ with $a_{-n} = \bar{a}_n$,
$\kappa_{\mathrm{real}}(1,N) = 1$ for all $N$.
\end{corollary}

\begin{proposition}\label{prop:single-mode}
For $f(x) = \cos(nx + \varphi)$:
\begin{equation}\label{eq:single-mode}
  \frac{\widetilde{\Gamma}_{\gamma,2}(f,f)(x)}
       {\widetilde{\Gamma}_\gamma(f,f)(x)}
  = |n|^\gamma \cdot
  \frac{1 + \alpha_n^2\,\cos(2nx+\theta)}
       {1 + \alpha_n\,\cos(2nx+\theta)},
\end{equation}
where $\alpha_n = 1 - 2^{\gamma-1}$ (independent of $n$)
and $\theta = 2\varphi$. The curvature is
\begin{equation}\label{eq:kappa1}
  \kappa_1(\gamma) = \frac{1 + \alpha^2}{1 + |\alpha|},
  \qquad \alpha = 1 - 2^{\gamma-1}.
\end{equation}
At $\gamma = 1$: $\alpha = 0$, giving $\kappa_1(1) = 1$.
For all $\gamma \neq 1$: $\kappa_1(\gamma) < 1$.
\end{proposition}

\begin{theorem}\label{thm:potential}
For $f(x) = \cos x$ and $V(x) = -\omega^2\cos x$:
\begin{equation}\label{eq:G2-ratio-potential}
  \frac{\Gamma_{L,2}(f,f)(x)}{\Gamma(f,f)(x)}
  = \frac{1 + \alpha^2\cos 2x + \tfrac{\omega^2}{2}(\cos x + \beta\cos 3x)}
         {1 + \alpha\cos 2x},
\end{equation}
where
$\alpha(\gamma) = 1 - 2^{\gamma-1}$ and
$\beta(\gamma) = (2^{\gamma+1} - 3^\gamma - 1)/2$.
\end{theorem}

\begin{proposition}[Refined contraction]\label{prop:refined}
At $\gamma = 1$, decompose $f \in \mathcal{T}_N^+$ along the
eigenbasis $\{\phi_k\}_{k=1}^N$ of $M(1) = R_{1/2}^{-1}\,R_{1/2}^{\circ 2}$.
Then the $k$-th component of the carr\'e du champ contracts at rate
\begin{equation}\label{eq:refined-contraction}
  \Gamma(P_t f, P_t f)_k \leq e^{-2(2k-1)t}\,\Gamma(f,f)_k,
  \qquad k = 1,\ldots,N.
\end{equation}
The total energy satisfies
\begin{equation}\label{eq:total-energy}
  \int_\T \Gamma(P_t f, P_t f)\,d\mu
  \leq \sum_{k=1}^N e^{-2(2k-1)t}\,\mathcal{E}_k(f),
\end{equation}
where $\mathcal{E}_k(f)$ is the energy in the $k$-th eigendirection.
The uniform bound $e^{-2t}\,\mathcal{E}(f)$ is sharp only for
functions concentrated on the first mode ($k=1$).
\end{proposition}

\begin{corollary}[Volume comparison]\label{cor:volume}
The $\Gamma_2$-ellipsoid
$E_2 = \{f : \Gamma_2(f,f) \leq 1\}$ and the $\Gamma$-ellipsoid
$E_1 = \{f : \Gamma(f,f) \leq 1\}$ on $\mathcal{T}_N^+$ satisfy
\begin{equation}\label{eq:volume-ratio}
  \frac{\mathrm{vol}(E_1)}{\mathrm{vol}(E_2)}
  = (\det M)^{1/2} = \bigl((2N-1)!!\bigr)^{1/2}
  = \bigl(\E[X^{2N}]\bigr)^{1/2},
\end{equation}
where $X \sim \mathcal{N}(0,1)$.
At $\gamma = 1$, the $\Gamma_2$-form is $(2N-1)!!^{1/2}$ times
more concentrating than the $\Gamma$-form in $N$-dimensional volume.
\end{corollary}

\begin{theorem}[Bakry-\'{E}mery curvature on $S^3$ with cosine drift]%
\label{thm:S3}
The operator $L = \Delta_{S^3} - \nabla V \cdot \nabla$ with $V(\theta)
= -c\cos\theta$ on $S^3$ satisfies
\begin{equation}
  \boxed{\mathrm{CD}(2-c,\,\infty)}\,.
\end{equation}
Equivalently, for all smooth $f \colon S^3 \to \R$:
\begin{equation}\label{eq:CD-S3}
  \Gamma_{L,2}(f,f) \;\ge\; (2-c)\,\Gamma(f,f),
\end{equation}
where $\Gamma(f,f) = |\nabla f|^2$ and $\Gamma_{L,2}(f,f) =
\tfrac{1}{2}[L\,\Gamma(f,f) - 2\,\Gamma(f,Lf)]$.
\end{theorem}

\begin{corollary}[Single-link Poincar\'{e} inequality]\label{cor:poincare}
For $c < 2$, the single-link conditional measure $\mu_\ell$ satisfies
\begin{equation}
  \Var_{\mu_\ell}(f) \;\le\; \frac{1}{2-c}\,\mathcal{E}_L(f,f),
\end{equation}
where $\mathcal{E}_L(f,f) = \int |\nabla f|^2\,d\mu_\ell$ is the
Dirichlet form.
\end{corollary}

\begin{corollary}[Gradient estimate]
For the semigroup $P_t^L = e^{tL}$:
\begin{equation}
  |\nabla P_t^L f|^2 \;\le\; e^{-2(2-c)t}\, P_t^L\!\bigl[|\nabla f|^2\bigr].
\end{equation}
\end{corollary}

\begin{proposition}[Collapse at the iterated-Brownian endpoint;
\S\ref{sec:ibm}]\label{prop:intro-ibm}
At $H=2$ ($\gamma=4$) the carr\'e du champ kernel
$\Psi_4(\xi,\eta)=\tfrac12(\xi^4+\eta^4-(\xi-\eta)^4)$ of the biharmonic
generator $\partial_x^4$ has rank $3$ and signature $(1,2)$: a single
positive direction against two negative ones. The diffusion's positive
cone has collapsed to a line.
\end{proposition}

\begin{corollary}[Spectrum, eigenvectors, and a commuting tower]
\label{cor:innov}
$M^{(j)}=R^{-1}R^{\Had j}=L^{-\top}D_jL^{\top}$ is similar to $D_j$;
this reproves Theorem~\ref{thm:graded}. The curvature eigenvectors are
the columns of $L^{-\top}$, the discrete differences $e_k-e_{k-1}$,
\emph{independent of the chaos level $j$}. Hence the whole tower
$\{M^{(j)}\}_{j\ge1}$ is a commuting family, simultaneously diagonalized
by the difference basis, and $\det M^{(j)}=\det D_j=\prod_k(k^j-(k-1)^j)$,
$\tr M^{(j)}=\tr D_j=N^j$ are immediate.
\end{corollary}

\begin{theorem}[Schur $=$ P\'olya--Schur on even orders]\label{thm:dict}
For integer $m\ge1$, the following are equivalent:
\emph{(i)} $m=1$;
\emph{(ii)} the carr\'e du champ kernel $\Psi_{2m}$ is positive
semidefinite;
\emph{(iii)} $e^{tu^{2m}}$ is a P\'olya--Schur multiplier, i.e.\ the flow
$e^{(-1)^m t\partial^{2m}}$ preserves $\LP$ for every $t\ge0$.
\end{theorem}

\begin{lemma}[Boundary Tanaka piece vanishes after \texorpdfstring{$\E_X$}{E\_X}]
\label{lem:bdy-zero}
$\E_X[g_\varepsilon'(0)]=0$.
\end{lemma}

\begin{definition}[Carr\'e du champ]\label{def:carre}
On $\Dom(D)\times\Dom(D)$ define the bilinear form
$\Carre(F,G)\coloneqq\langle DF,\,DG\rangle_\Energy$.
We call $\Carre$ the \emph{energy bracket} associated to the datum.
\end{definition}

\begin{definition}[Observable smooth core]\label{def:obs-core}
The \emph{observable smooth core} induced by $D_\Source$ is
\[
  \mathcal C_\Obs
  \;\coloneqq\;
  \bigl\{\,F\in\Hilb_\Obs : \iota F\in\Dom(D_\Source)\,\bigr\}.
\]
\end{definition}

\begin{assumption}[Density of the observable core]\label{ass:dense}
$\mathcal C_\Obs$ is dense in $\Hilb_\Obs$.
\end{assumption}

\begin{definition}[Intrinsic divergence]\label{def:int-div}
\[
  \delta_\Obs\coloneqq D_\Obs^{*}\colon\Dom(\delta_\Obs)\subseteq\Energy_\Obs
  \longrightarrow\Hilb_\Obs.
\]
\end{definition}

\begin{theorem}[Projected divergence formula]\label{thm:proj-div}
Let $u\in\Energy_\Obs$ satisfy $Ju\in\Dom(\delta_\Source)$. Then
$u\in\Dom(\delta_\Obs)$ and
\begin{equation}\label{eq:proj-div}
  \delta_\Obs u \;=\; P_\Obs\,\delta_\Source(Ju).
\end{equation}
\end{theorem}

\begin{corollary}[Adjoint compatibility, exact case]\label{cor:exact-intertwining}
Suppose $D_\Obs$ is the compression derivative of \cref{thm:compression}
and the inclusion $J$ intertwines the divergences exactly in the sense
of \cref{def:dintertwine}. Then for every $F\in\mathcal C_\Obs$,
\[
  D_\Obs F \;=\; J^{*}\,D_\Source(\iota F),
\]
which is the rigidity statement of the previous draft of this paper.
\end{corollary}

\begin{definition}[IBM occupation core]\label{def:cocc}
The \emph{IBM occupation core} is
\[
  \mathcal C_{\mathrm{occ}}
  \;\coloneqq\;\mathrm{span}\bigl\{\,F_T(\varphi)-\E F_T(\varphi):
   T>0,\ \varphi\in\mathscr S_\IBM\,\bigr\}\;\subseteq\;
   L^{2}(\Omega,\mathcal F_\IBM,\Prob).
\]
\end{definition}

\begin{proposition}[Source derivatives of the mollified core]
\label{prop:moll-deriv}
Set $(D_XX^\varepsilon_y)(\xi)\coloneqq(\rho_\varepsilon*\sigma_\cdot(\xi))(y)$
and $(\partial_yX^\varepsilon)(y)\coloneqq(\rho_\varepsilon'*X)(y)$. Then
for $\varphi\in\mathscr S_\IBM$, $T>0$, $\varepsilon>0$,
\begin{align}
  D_X F_{T,\varepsilon}(\varphi)(\xi)
  &\;=\;\int_0^T\varphi'\bigl(X^\varepsilon_{Y_s}\bigr)\,
         (D_XX^\varepsilon_{Y_s})(\xi)\,ds,
         \qquad\xi\in\R,
         \label{eq:DX-moll}\\[2pt]
  D_Y F_{T,\varepsilon}(\varphi)(r)
  &\;=\;\int_r^T\varphi'\bigl(X^\varepsilon_{Y_s}\bigr)\,
         (\partial_yX^\varepsilon)(Y_s)\,ds,
         \qquad r\in[0,T].
         \label{eq:DY-moll}
\end{align}
\end{proposition}

\begin{definition}[Occupation observable energy]\label{def:occ-energy}
The \emph{$\varepsilon$-occupation observable energy} is
\[
  \Energy_\IBM^{\mathrm{occ},\,\varepsilon}
  \;\coloneqq\;
  \overline{\bigl\{(D_XF,\,D_YF):F\in\mathcal C_{\mathrm{occ}}^{\,\varepsilon}\bigr\}}
  ^{\,L^{2}(\R)\oplus L^{2}(\R_{+})}
  \;\subseteq\;\Energy_\IBM.
\]
\end{definition}

\begin{lemma}[Scenery mollifier $L^{2}$-rate, uniform in $x$]
\label{lem:moll-rate}
Let $X$ be the two-sided Brownian scenery and $X^{\varepsilon}=
\rho_\varepsilon*X$ as in \cref{def:mollified}. Then \emph{uniformly}
for every $x\in\R$,
\begin{equation}\label{eq:moll-rate-L2}
  \E\bigl[(X^{\varepsilon}_x-X_x)^{2}\bigr]\;\le\;C_\rho\,\varepsilon,
  \qquad C_\rho\;\coloneqq\;\int_\R|v|\rho(v)\,dv\;<\;\infty,
\end{equation}
and consequently $\E|X^\varepsilon_x-X_x|\le C_\rho^{1/2}\varepsilon^{1/2}$
uniformly in $x$. In particular $X^\varepsilon_0\to 0$ in $L^{2}$ as
$\varepsilon\to 0$, since $X_0=0$ a.s.
\end{lemma}

\begin{lemma}[Scenery-derivative kernel: $L^{2}$ bound and rate]\label{lem:moll-H}
With $H_\varepsilon(y,\xi)\coloneqq(D_XX^\varepsilon_y)(\xi)=(\rho_\varepsilon*\sigma_\cdot(\xi))(y)$:
\begin{enumerate}
\item[(a)] $\|H_\varepsilon(y,\cdot)\|_{L^{2}(\R)}^{2}\le|y|+C_\rho\varepsilon$
  for every $y\in\R$;
\item[(b)] $\|H_\varepsilon(y,\cdot)-\sigma_y\|_{L^{2}(\R)}^{2}\le C'_\rho\varepsilon$
  for every $y\in\R$, with $C'_\rho$ depending only on the support of
  $\rho$.
\end{enumerate}
\end{lemma}

\begin{definition}[Second-order observable smooth core]
\label{def:obs-core-2}
$\mathcal C_\Obs^{(2)}\coloneqq
 \bigl\{F\in\Hilb_\Obs:\iota F\in\Dom(D_\Source^{(2)})\bigr\}$.
\end{definition}

\begin{definition}[Candidate second-order compression operator and energy]
\label{def:compression-2}
For $F\in\mathcal C_\Obs^{(2)}$, set
$D_\Obs^{(2),0}F\coloneqq D_\Source^{(2)}(\iota F)
\in\Energy_\Source^{(2)}$.
The \emph{candidate second-order observable energy} is
\[
  \Energy_\Obs^{(2)}
  \;\coloneqq\;
  \overline{\bigl\{\,D_\Source^{(2)}(\iota F):F\in\mathcal C_\Obs^{(2)}\,\bigr\}}
   ^{\,\Energy_\Source^{(2)}}
  \;\subseteq\;\Energy_\Source^{(2)},
\]
with isometric inclusion
$J^{(2)}\colon\Energy_\Obs^{(2)}\hookrightarrow\Energy_\Source^{(2)}$.
\end{definition}

\begin{theorem}[Conditional operator-It\^o transfer]\label{thm:transfer}
Assume \eqref{eq:source-ito} holds with $A_f(t)\in J(\Energy_\Obs)$,
so that there exists $B_f(t)\in\Energy_\Obs$ with $JB_f(t)=A_f(t)$, and
assume $B_f(t)$ lies in the lifted source-divergence domain
$\{u\in\Energy_\Obs:Ju\in\Dom(\delta_\Source)\}$. Suppose further that
$f(U_t)-f(U_0)$ is $\Prob$-a.s.\ $\mathcal F_\Obs$-measurable. Then
\begin{equation}\label{eq:obs-ito}
  f(U_t)-f(U_0)\;=\;\delta_\Obs\bigl(B_f(t)\bigr)\;+\;P_\Obs R_f(t),
\end{equation}
with $\delta_\Obs(B_f(t))=P_\Obs\,\delta_\Source(A_f(t))$.
\end{theorem}

\begin{proposition}[Fourier-mode bi-Laplacian shadow]
\label{prop:fourier-2nd}
Let $a=k^{2}/2$ and
\[
  q(t)\;\coloneqq\;\int_0^\infty e^{-as}\,p_t(s)\,ds,
  \qquad p_t(s)=\sqrt{\tfrac{2}{\pi t}}\,e^{-s^{2}/(2t)},\quad s\ge 0,
\]
so that $u_k(t,x)=e^{ikx}q(t)$. Then $q$ satisfies
\begin{equation}\label{eq:q-ode}
  q'(t)\;=\;\frac{a^{2}}{2}\,q(t)\;-\;\frac{a}{\sqrt{2\pi t}}
  \;=\;\frac{k^{4}}{8}\,q(t)\;-\;\frac{k^{2}}{2\sqrt{2\pi t}},
\end{equation}
and equivalently
\begin{equation}\label{eq:az-prop}
  \partial_t u_k(t,x)
  \;=\;\frac{1}{8}\,\Delta^{2}u_k(t,x)
       \;+\;\frac{\Delta f_k(x)}{2\sqrt{2\pi t}},
  \qquad f_k(x)=e^{ikx}.
\end{equation}
\end{proposition}

\begin{definition}[Semigroup correction density and integrated correction]
\label{def:sg-correction}
For $f\in\mathscr S(\R)$ and $t>0$, the \emph{semigroup correction
density} is
\begin{equation}\label{eq:sg-density}
  \mathcal C_\IBM^{\mathrm{sg}}(f;t,x)
  \;\coloneqq\;\frac{1}{8}\,\partial_x^{4}u(t,x)
   \;+\;\frac{1}{2\sqrt{2\pi t}}\,\partial_x^{2}f(x),
\end{equation}
and the \emph{integrated semigroup correction} is
\begin{equation}\label{eq:sg-integrated}
  C_\IBM^{\mathrm{sg}}(f;t,x)
  \;\coloneqq\;\int_0^t\mathcal C_\IBM^{\mathrm{sg}}(f;s,x)\,ds.
\end{equation}
\end{definition}

\begin{theorem}[Semigroup-level IBM correction]\label{thm:sg-correction}
For $f\in\mathscr S(\R)$ and $t>0$,
\begin{equation}\label{eq:sg-main}
  u(t,x)-f(x)\;=\;C_\IBM^{\mathrm{sg}}(f;t,x),
\end{equation}
equivalently $\partial_t u(t,x)=\mathcal C_\IBM^{\mathrm{sg}}(f;t,x)$.
The integrand defining $C_\IBM^{\mathrm{sg}}$ is integrable on
$(0,t]$: the boundary singularity
$s^{-1/2}\partial_x^{2}f(x)$ is of integrable type, since
$\int_0^t s^{-1/2}\,ds=2\sqrt t<\infty$ and $\partial_x^{2}f$ is
bounded for $f\in\mathscr S(\R)$.
\end{theorem}

\begin{corollary}[Conditional pathwise-to-semigroup consistency]
\label{cor:pathwise-to-sg}
Suppose, on a domain of test functions $f\in\mathscr S(\R)$ and time
horizons $t>0$, a pathwise / operator-It\^o identity
of the form \eqref{eq:pathwise-target} holds:
\[
  f(x+X_{|Y_t|})-f(x)\;=\;\delta_\IBM(B_f(t))+C_\IBM(f;t),
\]
with $\E[\delta_\IBM(B_f(t))]=0$ (centred divergence). Then necessarily
\begin{equation}\label{eq:consistency}
  \E[C_\IBM(f;t)]\;=\;C_\IBM^{\mathrm{sg}}(f;t,x)\;=\;u(t,x)-f(x).
\end{equation}
\end{corollary}

\begin{proposition}[Mollified pathwise It\^o-Tanaka identity]
\label{prop:moll-tanaka}
For every $\varepsilon>0$, $t\ge 0$, $f\in\mathscr S(\R)$,
\begin{equation}\label{eq:moll-tanaka}
  f(Z_t^\varepsilon)-f(Z_0^\varepsilon)
  \;=\;M_{\varepsilon,t}^{Y}\;+\;g_\varepsilon'(0)\,L_t^{0}(Y)
       \;+\;\tfrac12\!\int_0^t g_\varepsilon''(|Y_s|)\,ds,
\end{equation}
where $L_t^{0}(Y)$ is the Brownian local time of $Y$ at $0$ and
\begin{equation}\label{eq:moll-mart}
  M_{\varepsilon,t}^{Y}\;=\;\int_0^t g_\varepsilon'(|Y_s|)\,
   \mathrm{sgn}(Y_s)\,dY_s
\end{equation}
is a continuous $L^{2}$-martingale in $Y$ (conditional on $X$). The
derivatives in \eqref{eq:moll-tanaka} are explicit:
\[
  g_\varepsilon'(r)=f'(x+X^\varepsilon_r)\,\partial_rX^\varepsilon_r,
  \quad
  g_\varepsilon''(r)=f''(x+X^\varepsilon_r)\,(\partial_rX^\varepsilon_r)^{2}
   +f'(x+X^\varepsilon_r)\,\partial_r^{2}X^\varepsilon_r.
\]
\end{proposition}

\begin{theorem}[Expectation-level consistency at $\varepsilon>0$]
\label{thm:moll-consistency}
For every $f\in\mathscr S(\R)$, $\varepsilon>0$, and $t>0$,
\begin{equation}\label{eq:moll-exp-id}
  \E[C_{\IBM,\varepsilon}(f;t)]
   \;=\;U^\varepsilon(t,x)-v^\varepsilon(0,x).
\end{equation}
Consequently, as $\varepsilon\to 0$,
\begin{equation}\label{eq:moll-limit}
  \lim_{\varepsilon\to 0}\,\E[C_{\IBM,\varepsilon}(f;t)]
   \;=\;u(t,x)-f(x)
   \;=\;C_\IBM^{\mathrm{sg}}(f;t,x).
\end{equation}
\end{theorem}

\begin{theorem}[$L^{2}$-divergence of the first-chaos projection]
\label{prop:var-divergence}
Let $f\in\mathscr S(\R)$, $x\in\R$, $t>0$. Assume the
nondegeneracy condition
\begin{equation}\label{eq:nondegen}
  C(\eta)\;\coloneqq\;\E[f'(x+X_\eta)]\;=\;(P_\eta f')(x),
  \qquad\eta>0,\qquad\text{is not identically zero on }(0,\infty).
\end{equation}
Then
\begin{equation}\label{eq:var-diverges}
  \liminf_{\varepsilon\to 0}\,
   \Var\bigl(\mathrm{Proj}_1^{X}\,C_{\IBM,\varepsilon}(f;t)\bigr)\;=\;+\infty,
\end{equation}
and in particular $C_{\IBM,\varepsilon}(f;t)$ does not converge in
$L^{2}(\Omega)$ as $\varepsilon\to 0$. The hypothesis
\eqref{eq:nondegen} holds in particular whenever $f'(x)\ne 0$
(since $C(\eta)\to f'(x)$ as $\eta\to 0^{+}$).
\end{theorem}

\begin{assumption}[Local-time Sobolev moments]\label{assu:lt-moment}
For every $\eta\in(0,1/2)$ and $p\ge 2$,
\[
 \E_{Y}\bigl[\,\|L_{t}^{\cdot}(|Y|)\|_{H^{1/2-\eta}([0,M_{t}])}^{p}\,\bigr]<\infty.
\]
\end{assumption}

\begin{proposition}[Quantitative interior rate]\label{prop:interior-rate}
Assume \cref{assu:lt-moment}. Then for every
$\eta\in(0,1/2)$,
\begin{equation}\label{eq:int-rate}
 \bigl\|K_{\varepsilon}^{\mathrm{int,exact}}-K^{\mathrm{int}}\bigr\|_{L^{2}(\Omega_{Y};H^{-1}(\R))}
 \;\le\;C(f,t,\rho,\eta)\,\varepsilon^{1/2-\eta}.
\end{equation}
The same bound holds with $K_{\varepsilon}^{\mathrm{int}}$ in place
of $K_{\varepsilon}^{\mathrm{int,exact}}$.
\end{proposition}

\begin{lemma}[Scenery mollifier $L^{2}$-rate, uniform in $x$]
\label{lem:moll-rate}
For every $x\in\R$,
\begin{equation}\label{eq:moll-rate-L2}
  \E\bigl[(X^{\varepsilon}_x-X_x)^{2}\bigr]\;\le\;C_\rho\,\varepsilon,
  \qquad C_\rho\;\coloneqq\;\int_\R|v|\rho(v)\,dv,
\end{equation}
hence $\E|X^\varepsilon_x-X_x|\le C_\rho^{1/2}\varepsilon^{1/2}$
uniformly in $x$. In particular $X^\varepsilon_0\to 0$ in $L^{2}$ as
$\varepsilon\to 0$ since $X_0=0$ a.s.
\end{lemma}

\begin{lemma}[Scenery-derivative kernel: $L^{2}$ bound and rate]
\label{lem:moll-H}
With $H_\varepsilon(y,\xi)\coloneqq(D_X X^\varepsilon_y)(\xi)
=(\rho_\varepsilon*\sigma_\cdot(\xi))(y)$:
\begin{enumerate}
\item[(a)] $\|H_\varepsilon(y,\cdot)\|_{L^{2}(\R)}^{2}\le|y|+C_\rho\varepsilon$
  for every $y\in\R$.
\item[(b)] $\|H_\varepsilon(y,\cdot)-\sigma_y\|_{L^{2}(\R)}^{2}\le C'_\rho\varepsilon$
  for every $y\in\R$, with $C'_\rho$ depending only on $\supp\rho$.
\end{enumerate}
\end{lemma}

\begin{theorem}[Brownian-time semigroup correction]
\label{thm:bt-correction}
For $f\in\mathscr S(\R)$, set $u(t,x)\coloneqq\E[f(x+X_{|Y_t|})]$.
Then $u\in C^{\infty}((0,\infty)\times\R)$, $u(0+,x)=f(x)$, and for
every $t>0$,
\begin{equation}\label{eq:bt-correction}
  \partial_t u(t,x)
  \;=\;\frac{1}{8}\,\partial_x^{4}u(t,x)
       \;+\;\frac{1}{2\sqrt{2\pi t}}\,\partial_x^{2}f(x).
\end{equation}
\end{theorem}

\begin{corollary}[Integrated semigroup form]\label{cor:sg-integrated}
For $f\in\mathscr S(\R)$ and $t>0$,
$u(t,x)-f(x)=C_\IBM^{\mathrm{sg}}(f;t,x)$.
\end{corollary}

\begin{proposition}[Mollified pathwise It\^o--Tanaka identity]
\label{prop:moll-tanaka}
For every $\varepsilon>0$, $t\ge 0$, $f\in\mathscr S(\R)$,
\begin{equation}\label{eq:moll-tanaka}
  f(\IBM_t^{\varepsilon})-f(\IBM_0^{\varepsilon})
  \;=\;M_{\varepsilon,t}^{Y}\;+\;g_\varepsilon'(0)\,L_t^{0}(Y)
       \;+\;\tfrac12\!\int_0^t g_\varepsilon''(|Y_s|)\,ds,
\end{equation}
where
$M_{\varepsilon,t}^{Y}=\int_0^t g_\varepsilon'(|Y_s|)\sgn(Y_s)\,dY_s$
is a continuous $L^{2}$-martingale in $Y$ (conditional on $X$).
\end{proposition}

\begin{theorem}[Expectation-level consistency]
\label{thm:moll-consistency}
For every $f\in\mathscr S(\R)$, $\varepsilon>0$, and $t>0$,
\begin{equation}\label{eq:moll-exp-id}
  \E[C_{\IBM,\varepsilon}(f;t)]
   \;=\;U^\varepsilon(t,x)-v^\varepsilon(0,x),
\end{equation}
where $v^\varepsilon(r,x)=\E_X[f(x+U_r)]$ and
$U^\varepsilon(t,x)=\E[f(x+U_{|Y_t|})]
=\int_0^\infty v^\varepsilon(r,x)\,p_t(r)\,dr$. Consequently
\begin{equation}\label{eq:moll-limit}
  \lim_{\varepsilon\to 0}\E[C_{\IBM,\varepsilon}(f;t)]
   \;=\;u(t,x)-f(x)
   \;=\;C_\IBM^{\mathrm{sg}}(f;t,x),
\end{equation}
with $u(t,x)=\E[f(x+X_{|Y_t|})]$ and $C_\IBM^{\mathrm{sg}}$ from
\cref{def:sg-correction}.
\end{theorem}

\begin{lemma}[Conditional first-scenery-chaos projection]
\label{lem:proj1-X}
For $F\in\mathbb D^{1,2}(\Omega_X\times\Omega_Y)$ in the scenery
direction,
\begin{equation}\label{eq:proj1-X}
  \Pir_1^{X}F
   \;=\;\delta_X\bigl(K_F(\cdot\,;Y)\bigr),
  \qquad
  K_F(w;Y)\;\coloneqq\;\E_X[D_w^{X}F\mid Y],
\end{equation}
with $K_F(\cdot;Y)\in L^{2}(\R,dw)$ a.s.
\end{lemma}

\begin{lemma}[Sobolev gradient blow-up under $L^{2}$ approximation]
\label{lem:H1-blowup}
Let $u_\varepsilon\to u$ in $L^{2}(\R)$, with each
$u_\varepsilon\in C^{1}(\R)\cap H^{1}(\R)$, and $u\notin H^{1}(\R)$.
Then $\liminf_{\varepsilon\to 0}\|u_\varepsilon'\|_{L^{2}(\R)}=+\infty$.
\end{lemma}

\begin{theorem}[$L^{2}$-divergence of the first-chaos projection]
\label{thm:var-divergence}
Let $f\in\mathscr S(\R)$, $x\in\R$, $t>0$. Assume the nondegeneracy
condition
\begin{equation}\label{eq:nondegen}
  C(\eta)\;\coloneqq\;\E[f'(x+X_\eta)]\;=\;(P_\eta f')(x),
  \qquad\eta>0,
\end{equation}
is not identically zero on $(0,\infty)$ (in particular, this holds
whenever $f'(x)\ne 0$, since $C(\eta)\to f'(x)$ as $\eta\to 0^{+}$).
Then
\begin{equation}\label{eq:var-diverges}
  \liminf_{\varepsilon\to 0}\,
   \Var\bigl(\Pir_1^{X}\,C_{\IBM,\varepsilon}(f;t)\bigr)\;=\;+\infty,
\end{equation}
and in particular $C_{\IBM,\varepsilon}(f;t)$ does not converge in
$L^{2}(\Omega)$ as $\varepsilon\to 0$.
\end{theorem}

\begin{lemma}[Boundary-layer residual vanishing]\label{lem:bdy-layer-vanish}
For every $f\in\mathscr S(\R)$,
\[
 R_{\varepsilon}^{\mathrm{layer}}\;\xrightarrow[\varepsilon\to 0]{}\;0
 \quad\text{in }L^{2}\bigl(\Omega_{Y};\,L^{2}(\R,dw)\bigr),
\]
and hence in $L^{2}(\Omega_{Y};H^{-1}(\R))$ via the continuous
embedding $L^{2}\hookrightarrow H^{-1}$. Moreover the bound
\begin{equation}\label{eq:R-layer-bound}
 \|R_{\varepsilon}^{\mathrm{layer}}\|_{L^{2}(\R)}
 \;\le\;C(f,\rho)\,\varepsilon^{1/2}\,\|L\|_{\infty}
 \quad\text{a.s.\ in }Y
\end{equation}
holds with $C(f,\rho)$ depending only on
$\|f'''\|_{\infty},\|f^{(5)}\|_{\infty}$, $c$, $\|\rho\|_{\infty}$,
and $\int\rho^{2}$.
\end{lemma}

\begin{theorem}[Interior first-chaos $H^{-1}$ convergence]
\label{thm:interior}
Let $f\in\mathscr S(\R)$. Then both $K_{\varepsilon}^{\mathrm{int}}$
and $K_{\varepsilon}^{\mathrm{int,exact}}$ converge to the same limit
\[
 K_{\varepsilon}^{\mathrm{int}},\,K_{\varepsilon}^{\mathrm{int,exact}}
 \;\xrightarrow[\varepsilon\to 0]{}\;K^{\mathrm{int}}
 \quad\text{in }L^{2}\bigl(\Omega_{Y};\,H^{-1}(\R,dw)\bigr),
\]
with
\begin{equation}\label{eq:Kint-limit}
 K^{\mathrm{int}}(w\mid Y)
 =\tfrac12\bigl[T_{1}^{*}(w\mid Y)+B(w)L(w)-\partial_{w}\bigl(C(w)L(w)\bigr)\bigr],
\end{equation}
where $T_{1}^{*}(w\mid Y)=\mathbf 1_{w\ge 0}\int_{w}^{M_{t}}A(r)L(r)\,dr$,
$L=L_{t}^{\cdot}(|Y|)$, $M_{t}=\sup_{[0,t]}|Y_{s}|$, and $A,B,C$ are
the heat-semigroup limits of $A_\varepsilon,B_\varepsilon,C_\varepsilon$.
\end{theorem}

\begin{proposition}[Quantitative interior rate, conditional]\label{prop:interior-rate}
Assume \cref{assu:lt-moment}. Then for every $\eta\in(0,1/2)$,
\begin{equation}\label{eq:int-rate}
 \bigl\|K_{\varepsilon}^{\mathrm{int,exact}}-K^{\mathrm{int}}\bigr\|_{L^{2}(\Omega_{Y};H^{-1}(\R))}
 \;\le\;C(f,t,\rho,\eta)\,\varepsilon^{1/2-\eta}.
\end{equation}
The same bound holds with $K_\varepsilon^{\mathrm{int}}$ in place
of $K_\varepsilon^{\mathrm{int,exact}}$. The rate is conditional on
\cref{assu:lt-moment}; the qualitative convergence
(\cref{thm:interior}) is not.
\end{proposition}

\begin{corollary}[First-chaos dual closure of $\Pir_1^{X}C_{\IBM,\varepsilon}$]
\label{cor:proj1-closure}
At every $\varepsilon>0$, $\Pir_1^{X}C_{\IBM,\varepsilon}(f;t)$ is
an honest first-chaos random variable with conditional Malliavin
kernel $K_\varepsilon\in L^{2}(\Omega_{Y};L^{2}(\R))$;
\cref{cor:combined} gives $K_\varepsilon\to K$ in
$L^{2}(\Omega_{Y};H^{-1}(\R))=\Energy_{\IBM,1}^{-}$, with limit
kernel $K$ generically only $H^{-1}$ (not $L^{2}$), so the limit
object is a generalized $Y$-conditioned first-chaos functional
(\cref{def:first-chaos-block}) rather than an $L^{2}(\Omega_X)$
random variable. Convergence is the duality-pairing convergence:
for every $\Phi\in\Energy_{\IBM,1}^{+}=L^{2}(\Omega_Y;H^{1}(\R))$,
\[
 \bigl\langle\Pir_{1}^{X}C_{\IBM,\varepsilon}(f;t),\Phi\bigr\rangle_{1,*}
 \;\xrightarrow[\varepsilon\to 0]{}\;
 \E_{Y}\!\bigl[\langle K(\cdot\mid Y),\Phi(\cdot\mid Y)\rangle_{H^{-1},H^{1}}\bigr],
\]
including the special case of deterministic $\phi\in H^{1}(\R)$.
Under \cref{assu:lt-moment}, the rate is $\varepsilon^{1/2-\eta}$.
\end{corollary}

\begin{lemma}[Boundary Tanaka piece vanishes after $\E_X$]
\label{lem:bdy-zero}
$\E_X[g_\varepsilon'(0)]=0$.
\end{lemma}

\begin{proposition}[Channel enumeration]\label{prop:channels}
For every fixed $\varepsilon>0$ and $r\ge 0$,
\begin{align*}
 \Pir_2^X[f''(x+U_r)V_r^{2}]
 &=\Channel{0,0}+\Channel{2,V}+\Channel{2,\mathrm{c}}+\Channel{4},\\
 \Pir_2^X[f'(x+U_r)W_r]
 &=\Channel{1}+\Channel{3},
\end{align*}
where (with $h^{(k)}_{m,r}=h^{(k)}_{m,r,\varepsilon}$):
\begin{align*}
 \Channel{0,0}\,\,&\coloneqq\E_X[f''(x+U_r)]\cdot I_2^X(\rho_\varepsilon(r-\cdot)^{\otimes 2}),\\
 \Channel{2,V}&\coloneqq\sigma_V^{2}\cdot I_2^X(h^{(2)}_{2,r}),\\
 \Channel{2,\mathrm{c}}&\coloneqq 4\cdot I_2^X(h^{(2)}_{2,r}\otimes_1\rho_\varepsilon(r-\cdot)^{\otimes 2}),\\
 \Channel{4}&\coloneqq 12\cdot I_2^X(h^{(2)}_{4,r}\otimes_2\rho_\varepsilon(r-\cdot)^{\otimes 2}),\\
 \Channel{1}&\coloneqq I_2^X(h^{(1)}_{1,r}\,\widetilde\otimes\,\rho_\varepsilon'(r-\cdot)),\\
 \Channel{3}&\coloneqq 3\cdot I_2^X(h^{(1)}_{3,r}\otimes_1\rho_\varepsilon'(r-\cdot)).
\end{align*}
There are no further chaos-2 contributions.
\end{proposition}

\begin{theorem}[$(2,0)$ energy-contraction channel decomposition]
\label{thm:2-0}
For every $f\in\mathscr S(\R)$, $t\ge 0$, $\varepsilon>0$,
\begin{equation}\label{eq:2-0-explicit}
 \Pir_{2,0}\,C_{\IBM,\varepsilon}(f;t)
 \;=\;\sqrt{\tfrac{2t}{\pi}}\,\Pir_2^X[f'(x+U_0)V_0]
   +\tfrac12\!\int_0^t\!\E_Y\!\bigl[\Pir_2^X g_\varepsilon''(|Y_s|)\bigr]\,ds,
\end{equation}
with the second-chaos integrand given by \cref{prop:channels} as
$\Channel{0,0}+\Channel{2,V}+\Channel{2,\mathrm{c}}+\Channel{4}+\Channel{1}+\Channel{3}$
at $r=|Y_s|$. The expression lies in $\Hilb_2^X\otimes\Hilb_0^Y$ at
every $\varepsilon>0$.
\end{theorem}

\begin{proposition}[Boundary $(2,0)$ kernel]\label{prop:2-0-bdy}
\(
 \Pir_2^X[f'(x+U_0)V_0]
 =I_2^X\!\bigl(h^{(1)}_{1,0,\varepsilon}\,\widetilde\otimes\,\rho_\varepsilon(0-\cdot)\bigr).
\)
\end{proposition}

\begin{proposition}[Fourier-mode bi-Laplacian shadow]
\label{prop:fourier-2nd}
Let $a=k^{2}/2$ and $q(t)\coloneqq\int_0^\infty e^{-as}p_t(s)\,ds$,
so $u_k(t,x)=e^{ikx}q(t)$. Then
\begin{equation}\label{eq:q-ode}
  q'(t)\;=\;\frac{a^{2}}{2}\,q(t)\;-\;\frac{a}{\sqrt{2\pi t}}
  \;=\;\frac{k^{4}}{8}q(t)-\frac{k^{2}}{2\sqrt{2\pi t}},
\end{equation}
and equivalently
$\partial_t u_k(t,x)=\tfrac18\Delta^{2}u_k(t,x)+\Delta f_k(x)/(2\sqrt{2\pi t})$
for $f_k(x)=e^{ikx}$.
\end{proposition}

\begin{definition}[\texorpdfstring{Observable It\^o identity}{Observable Ito identity}]\label{def:observable}
An \emph{observable It\^o identity} is a triple $(X,L,\mathcal T)$ in
which
\begin{itemize}
\item[$(\mathrm i)$] $X=(X_t)_{t\ge 0}$ is a c\`adl\`ag process on a
Polish space $E$, defined on $(\Omega,\mathcal F,\Prob)$;
\item[$(\mathrm{ii})$] $\mathcal T\subset C_b(E)$ is a linear test class;
\item[$(\mathrm{iii})$] $L\colon\mathcal T\to C_b(E)$ is linear; and
\item[$(\mathrm{iv})$] for every $f\in\mathcal T$ the process
\begin{equation}\label{eq:martingale-problem}
  M_t[f]\;:=\;f(X_t)-f(X_0)-\int_0^t Lf(X_s)\,ds,\qquad t\ge 0,
\end{equation}
is a martingale with respect to the natural filtration
$\mathcal F^X_t:=\sigma(X_u:u\le t)$.
\end{itemize}
\end{definition}

\begin{definition}[Energy lift]\label{def:energy-lift}
An \emph{energy lift} of an observable It\^o identity
$(X,L,\mathcal T)$ is a quintuple
\[
  \bigl(\mathcal H,\;\mathcal U,\;\delta,\;D,\;(u^{\,\cdot}_f)_{f\in\mathcal T}\bigr)
\]
in which:
\begin{itemize}
\item[$(\mathrm i)$] $\mathcal H$ is a complex Hilbert space, or a
rigged Hilbert triple $\mathcal H_+\subset\mathcal H\subset\mathcal H_-$,
with $L^2(\Omega,\mathcal F^X,\Prob)\subset\mathcal H$ as a dense
subspace;
\item[$(\mathrm{ii})$] $\mathcal U$ is a Hilbert space of test directions;
\item[$(\mathrm{iii})$] $\delta\colon\Dom(\delta)\subset\mathcal U\to L^2(\Omega)$
is a closed, densely-defined operator (the \emph{divergence}), with
closed adjoint $D=\delta^{*}\colon\Dom(D)\subset L^2(\Omega)\to\mathcal U$
(the \emph{adjoint derivative}), satisfying the integration-by-parts
identity
\begin{equation}\label{eq:IBP}
  \E\!\bigl[F\cdot\delta(u)\bigr]
  \;=\;\E\!\bigl[\langle DF,u\rangle_{\mathcal U}\bigr],
  \qquad F\in\Dom(D),\ u\in\Dom(\delta);
\end{equation}
\item[$(\mathrm{iv})$] for every $f\in\mathcal T$ there is a
predictable direction
$u^{\,\cdot}_f\colon[0,\infty)\to\mathcal U$ such that
\begin{equation}\label{eq:M-as-delta}
  M_t[f]\;=\;\delta\!\bigl(u_f^{[0,t]}\bigr)\quad\text{in }L^2(\Omega),
  \qquad t\ge 0,
\end{equation}
where $u_f^{[0,t]}$ is the restriction of $u_f^{\,\cdot}$ to $[0,t]$.
\end{itemize}
\end{definition}

\begin{definition}[Additive integrable family]\label{def:additive-family}
Let $\mathcal N=(\mathcal F_{s,t})$ be a noise. An \emph{additive
integrable family} on $\mathcal N$ is a collection
$X=(X_{s,t})_{s\le t}$ such that:
\begin{itemize}
\item[$(\mathrm i)$] $X_{s,t}\in L^2(\mathcal F_{s,t})$ for every $s\le t$;
\item[$(\mathrm{ii})$] for every $r\le s\le t$,
\begin{equation}\label{eq:additivity}
  X_{r,t}\;=\;X_{r,s}+X_{s,t}\quad\text{in }L^2(\mathcal F_{r,t}),
\end{equation}
where the right-hand side is read via the canonical embeddings
$L^2(\mathcal F_{r,s})\hookrightarrow L^2(\mathcal F_{r,t})$ and
$L^2(\mathcal F_{s,t})\hookrightarrow L^2(\mathcal F_{r,t})$ of
\cref{rem:noise-l2-tensor}.
\end{itemize}
The family $X$ is \emph{centered} if $\E[X_{s,t}]=0$ for every $s\le t$.
\end{definition}

\begin{definition}[First chaos; classical subnoise]\label{def:classical-subnoise}
The \emph{first chaos} $I_1(\mathcal N)$ of $\mathcal N$ is the
closed linear subspace of $\bigoplus_{s\le t}L^2(\mathcal F_{s,t})$
spanned by all additive integrable families on $\mathcal N$ in the
sense of \cref{def:additive-family}. The \emph{classical subnoise}
$\mathcal N^{\mathrm{cl}}=(\mathcal F^{\mathrm{cl}}_{s,t})$ is the
subnoise generated by $I_1(\mathcal N)$:
\[
  \mathcal F^{\mathrm{cl}}_{s,t}
  :=\sigma\bigl(\,X_{s,t}\;:\;X\text{ an additive integrable family on }\mathcal N\,\bigr),
  \qquad s\le t.
\]
\end{definition}

\begin{definition}[Classical innovation reduction]\label{def:cir}
A \emph{classical innovation reduction} of an observable It\^o
identity $(X,L,\mathcal T)$ is a stochastic process
$Z=(Z_t)_{t\ge 0}$ on $(\Omega,\mathcal F,\Prob)$ such that:
\begin{itemize}
\item[$(\mathrm i)$] $Z$ is a L\'evy process (Brownian, Poisson,
compound Poisson, or finite-dimensional L\'evy), and is adapted to
the natural filtration $\mathcal F^X_t$;
\item[$(\mathrm{ii})$] the noise $\mathcal N_Z$ generated by $Z$ is a
subnoise of the classical subnoise $\mathcal N_X^{\mathrm{cl}}$ of
$X$, and is nontrivial in the sense that
$\mathcal F^Z_{s,t}\neq\{\emptyset,\Omega\}\bmod\Prob$ for some $s<t$;
\item[$(\mathrm{iii})$] for every $f\in\mathcal T$ there exists an
$\mathcal F^X$-predictable integrand $H[f]$ such that
\begin{equation}\label{eq:cir-representation}
  M_t[f]\;=\;\int_0^t H_s[f]\,dZ_s\quad\text{in }L^2(\Omega),
  \qquad t\ge 0,
\end{equation}
and the predictable representation $H[f]$ determines $M[f]$ uniquely.
\end{itemize}
\end{definition}

\begin{lemma}[First-chaos confinement]\label{lem:seed}
Let $\mathcal N=(\mathcal F_{s,t})$ be a noise and let $(T_{s,t})$ be
an interval-additive deterministic seed in the sense of
\cref{def:seed}. For every compatible $h\in H_\infty$, define
\begin{equation}\label{eq:X-family}
  X_{s,t}\;:=\;T_{s,t}(h_{s,t})-\E\!\bigl[T_{s,t}(h_{s,t})\bigr],
  \qquad s\le t.
\end{equation}
Then:
\begin{enumerate}
\item[$(\mathrm i)$] $X_{s,t}\in L^2(\mathcal F_{s,t})$ is centered
for every $s\le t$;
\item[$(\mathrm{ii})$] $(X_{s,t})$ is additive:
\[
  X_{r,t}\;=\;X_{r,s}+X_{s,t}
  \quad\text{in }L^2(\mathcal F_{r,t}),\quad r\le s\le t;
\]
\item[$(\mathrm{iii})$] $(X_{s,t})\in I_1(\mathcal N)$.
\end{enumerate}
If, in addition, $\mathcal N$ is black in the sense of
\cref{def:black}, then $X_{s,t}=0$ almost surely for every $s\le t$,
and the seed reduces to its deterministic mean:
\begin{equation}\label{eq:seed-deterministic}
  T_{s,t}(h_{s,t})\;=\;\E\!\bigl[T_{s,t}(h_{s,t})\bigr]
  \qquad\text{for every compatible }h.
\end{equation}
\end{lemma}

\begin{definition}[Leibniz defect]\label{def:leibniz-defect}
The \emph{Leibniz defect} of $D$ on $\mathcal A$ is the bilinear map
$\mathfrak L_D\colon\mathcal A\times\mathcal A\to\mathcal U$ given by
\begin{equation}\label{eq:leibniz-defect}
  \mathfrak L_D(F,G)\;:=\;D(FG)-F\,DG-G\,DF,
  \qquad F,G\in\mathcal A.
\end{equation}
We say $D$ is \emph{first-order on $\mathcal A$} if
$\mathfrak L_D\equiv 0$, and that $(\mathcal A,D)$ is a
\emph{derivation pair} in this case.
\end{definition}

\begin{definition}[Two-point product defect]\label{def:two-point-defect}
The \emph{two-point product defect} of the flow $\Phi$ on
$f,g\in\mathcal T^{(1)}$ is the function
\begin{equation}\label{eq:two-point-defect}
  \mathfrak D^{(2)}(f,g)(x,y)
  \;:=\;
  L^{(2)}(f\otimes g)(x,y)
  -(L^{(1)}f)(x)\,g(y)
  -f(x)\,(L^{(1)}g)(y),
\end{equation}
read on $\R^{2}$ (or on its symmetric quotient as appropriate).
\end{definition}

\begin{proposition}[Zero defect for independent Brownian motion]\label{prop:defect-indep}
Let $\Phi$ be the stochastic flow of independent Brownian motions
on $\R$, with $L^{(1)}=\tfrac{1}{2}\partial_x^2$ and
$L^{(2)}=\tfrac{1}{2}(\partial_x^2+\partial_y^2)$ on
$\mathcal T^{(1)}=\mathcal T^{(2)}=C_c^{\infty}$. Then
\begin{equation}\label{eq:defect-indep-zero}
  \mathfrak D^{(2)}(f,g)(x,y)\;\equiv\;0,
  \qquad f,g\in C_c^{\infty}(\R),\ (x,y)\in\R^2.
\end{equation}
\end{proposition}

\begin{proposition}[Common-driving flow: global defect]\label{prop:defect-common}
Let $\Phi$ be the flow on $\R$ driven by a single common Brownian
motion $W$, $X_t^{(x)}=x+W_t$, with two-point generator
$L^{(2)}=\tfrac{1}{2}(\partial_x+\partial_y)^2
=\tfrac{1}{2}(\partial_x^2+2\partial_{xy}+\partial_y^2)$. Then
\begin{equation}\label{eq:defect-common}
  \mathfrak D^{(2)}(f,g)(x,y)\;=\;f'(x)\,g'(y),\qquad (x,y)\in\R^2.
\end{equation}
\end{proposition}

\begin{proposition}[Hidden-clock Tweedie]\label{prop:tweedie}
With $\phi_v$ the $\mathcal N(0,v)$ density,
\begin{equation}\label{eq:hctweedie}
  \partial_x\log p_t(x)=\E\!\left[-\frac{x-a(t)X_0}{\sigma(t)^2 S_t}\ \middle|\ X_t=x\right],
\end{equation}
the posterior being the joint law of $(X_0,S_t)\mid X_t=x$.
\end{proposition}

\begin{proposition}[Unavoidable latent-clock term]\label{prop:postmean}
Let $\tilde\E[\,\cdot\,]=\E[\,\cdot/S_t\mid x]/\E[1/S_t\mid x]$ be the
precision-weighted posterior. Then
\begin{equation}
  a(t)\,\tilde\E[X_0\mid x]=x+\frac{\sigma(t)^2}{\E[1/S_t\mid x]}\,\partial_x\log p_t(x).
\end{equation}
The ordinary posterior mean $\E[X_0\mid x]$ coincides with $\tilde\E[X_0\mid x]$
\emph{iff} $S_t\perp X_0\mid X_t$, which fails for non-Gaussian data. Hence
passing between the score and $\E[X_0\mid x]$ requires the joint $(X_0,S_t)$
posterior, not a scalar clock moment.
\end{proposition}

\begin{mainthm}[Obstruction for deterministic representers]\label{thmE}
Under the hypotheses of Theorem~\ref{thmD}, if $(\delta_M^{\mathrm{ext}},\HM^{\mathrm{ext}})$ admits a cylindrical structure with deterministic representers $\kappa_i$ and coordinates $\xi_i = M_{t_i}$, then $\sigma$ is deterministic, and consequently $\langle M\rangle_T = \int_0^T\sigma_t^2\,dt$ is deterministic. In particular, no deterministic cylindrical structure exists when $\sigma$ is genuinely stochastic.
\end{mainthm}

\begin{definition}[Predictable projection]\label{def:pred_proj}
The \emph{predictable projection} $\Pi_X$ is the orthogonal projection in $L^2(\Omega; \HX)$ onto the closed subspace of $\mathcal{P}$-measurable $\HX$-valued processes.
\end{definition}

\begin{lemma}[Adjoint existence]\label{lem:adjoint}
Let $(\HX, \delta_X)$ be an energy space with $\delta_X$ densely defined and closable (Definition~\ref{def:energy}). Then the Hilbert space adjoint $D_X := \delta_X^*$ is a well-defined, closed, densely defined operator from $L^2(\Omega)$ to $L^2(\Omega; \HX)$.
\end{lemma}

\begin{definition}[Operator derivative]\label{def:opderiv}
For $F \in L^2(\Omega)$ such that the functional $u \mapsto \E[F \cdot \delta_X(u)]$ is continuous on $\dom(\delta_X) \subseteq L^2(\Omega; \HX)$ with respect to the $L^2(\Omega; \HX)$-norm, the \emph{operator derivative} $D_X F$ is the unique element of $L^2(\Omega; \HX)$ satisfying
\begin{equation}\label{eq:adj}
\E[F \cdot \delta_X(u)] = \E[\langle D_X F, u \rangle_{\HX}] \quad \text{for all } u \in \dom(\delta_X).
\end{equation}
Existence follows from the Riesz representation theorem applied to the continuous functional $u \mapsto \E[F \cdot \delta_X(u)]$ on $\overline{\dom(\delta_X)}^{L^2(\Omega;\HX)}$; uniqueness from the density of $\dom(\delta_X)$.
\end{definition}

\begin{proposition}[Intrinsic properties]\label{prop:intrinsic}
Let $D_X$ be defined by~\eqref{eq:adj}. Then:
\begin{enumerate}[label=\textup{(\alph*)}]
\item \textup{Linearity:} $D_X(\alpha F + \beta G) = \alpha\,D_X F + \beta\,D_X G$ for $\alpha,\beta \in \R$.
\item \textup{Closedness:} If $F_n \to F$ in $L^2(\Omega)$ and $D_X F_n \to g$ in $L^2(\Omega; \HX)$, then $F \in \dom(D_X)$ and $D_X F = g$.
\item \textup{Constants:} $D_X(c) = 0$ for $c \in \R$.
\item \textup{Uniqueness:} $D_X F$ is uniquely determined by~\eqref{eq:adj}.
\end{enumerate}
\end{proposition}

\begin{theorem}[Unified Clark--Ocone representation]\label{thm:CO}
Let $X$ have energy space $(\HX, \delta_X)$, predictable projection $\Pi_X$, and $D_X = \delta_X^*$. Assume:
\begin{enumerate}[label=\textup{(\roman*)}]
\item \textup{Centered integrals:} $\E[\delta_X(u)] = 0$ for all $u \in \dom(\delta_X)$.
\item \textup{Isometry on predictable processes:} Condition~\ref{cond:iso} holds.
\item \textup{Predictable representation property (PRP):} Every centered ${\FX}_T$-measurable $\tilde{F} \in L^2(\Omega)$ can be written as $\tilde{F} = \delta_X(v)$ for some predictable $v \in L^2(\Omega; \HX)$.
\end{enumerate}
Then for ${\FX}_T$-measurable $F \in L^2(\Omega)$:
\begin{equation}\label{eq:clark_ocone}
F = \E[F] + \delta_X(\Pi_X D_X F).
\end{equation}
Equivalently, $(\Id - \E) = \delta_X \circ \Pi_X \circ D_X$ on $L^2(\Omega, {\FX}_T, P)$.
\end{theorem}

\begin{proposition}[Explicit form of $D_{\tilde{N}}$]\label{prop:poisson_explicit}
For $\mathcal{F}_T^N$-measurable $F \in L^2(\Omega)$:
$(D_{\tilde{N}} F)_t = \E[\mathcal{D}_t^+ F \mid \mathcal{F}_{t-}]$, $dt \otimes dP$-a.e.
\end{proposition}

\begin{definition}[Gaussian Volterra process]\label{def:volterra}
A centered Gaussian process $X_t = \int_0^t K(t,s)\,dW_s$ with deterministic Volterra kernel $K$ and $\int_0^T\int_0^t K(t,s)^2\,ds\,dt < \infty$. Covariance: $R_X(t,s) = \int_0^{t\wedge s}K(t,r)K(s,r)\,dr$.
\end{definition}

\begin{definition}[Cameron--Martin space]\label{def:CM}
The RKHS $\HX$ is the completion of $\mathrm{span}\{k_t : t \in [0,T]\}$ under $\langle k_t, k_s\rangle_{\HX} := R_X(t,s)$, where $k_t := R_X(t,\cdot)$ satisfies $\langle h, k_t\rangle_{\HX} = h(t)$.
\end{definition}

\begin{definition}[Isonormal Gaussian map]\label{def:isonormal}
$I_X : \HX \to L^2(\Omega)$ defined by $I_X(k_t) := X_t$ extends to an isometry: $\E[I_X(h)I_X(g)] = \langle h,g\rangle_{\HX}$.
\end{definition}

\begin{lemma}[Measurability preservation]\label{lem:meas_pres}
Let $W$ be a Brownian motion with filtration $(\mathcal{F}_t)$. If $F$ is $\mathcal{F}_s$-measurable and $F \in \mathbb{D}^{1,2}$, then $D_t^W F$ is $\mathcal{F}_s$-measurable for every $t \in [0,T]$, and $D_t^W F = 0$ for $t > s$.
\end{lemma}

\begin{corollary}\label{cor:adapted_mall}
If $(\sigma_s)_{s \in [0,T]}$ is a progressively measurable process with $\sigma_s \in \mathbb{D}^{1,2}$ for a.e.~$s$, then for fixed~$t$, the process $s \mapsto D_t^W(\sigma_s)$ is $\mathcal{F}_s$-adapted for $s \ge t$, and $D_t^W(\sigma_s) = 0$ for $s < t$.
\end{corollary}

\begin{definition}[Adapted subspace]\label{def:adapted}
${\HX}_t := \overline{\mathrm{span}\{k_s : s \le t\}} \subset \HX$ with orthogonal projection $P_t : \HX \to {\HX}_t$.
\end{definition}

\begin{definition}[Gaussian predictable projection]\label{def:gauss_pred}
$(\Pi_Xu)_t := P_t(\E[u\mid{\FX}_t])$: conditional expectation in $\omega$, RKHS projection in $\HX$.
\end{definition}

\begin{lemma}[RKHS projection = conditional expectation on first chaos]\label{lem:rkhs_cond}
For $h \in \HX$: $I_X(P_th) = \E[I_X(h)\mid{\FX}_t]$.
\end{lemma}

\begin{theorem}[Factorization for fBM]\label{thm:fact_fbm}
For fBM $\BH$ with $H \in (0,1)$, $H \neq 1/2$, and $F \in L^2(\Omega,{\FBH}_T)$ with $D_{\BH}F \in L^2(\Omega;\HH)$:
\begin{equation}\label{eq:fact_fbm}
(\Id-\E)\,F = \delta_H(\Pi_{\BH}D_{\BH}F),
\end{equation}
where we write $\delta_H := \delta_{\BH}$, $D_H := D_{\BH}$, and $\Pi_H := \Pi_{\BH}$ when the subscript is clear from context.
\end{theorem}

\begin{theorem}[Gubinelli derivative as predictable projection]\label{thm:gub}
Under the hypotheses of Theorem~\ref{thm:fact_fbm}, let $Y_t := \E[F\mid{\FBH}_t]$. Then
\begin{equation}\label{eq:gub}
Y_t - Y_s = \langle(\Pi_{\BH}D_{\BH}F)_s, k_t-k_s\rangle_{\HH} + R_{s,t}, \quad \E[R_{s,t}^2] = O(|t-s|^{\min(4H,\,2H+1)}).
\end{equation}
For $H < 1/2$: $\min(4H, 2H+1) = 4H$, recovering the Gubinelli regularity. For $H > 1/2$: $\min(4H, 2H+1) = 2H+1 > 2$, so the remainder decays faster than any power of $|t-s|^2$---the expansion is even better behaved. The operator approach is uniform in~$H$; the restriction $H < 1/2$ in rough path theory reflects path irregularity, not algebraic structure. The identity $(\Pi_{\BH}D_{\BH}F)_s = Y'_s$ is an equality in $L^2(\Omega; \HH)$; it identifies the Gubinelli derivative as an $L^2$-algebraic object, not as a pathwise-defined controlled path.
\end{theorem}

\begin{definition}[Decreusefond--\"Ust\"unel conditions]\label{def:DU}
A Volterra kernel $K$ (Definition~\ref{def:volterra}) satisfies the \emph{Decreusefond--\"Ust\"unel conditions}~\cite{Decreusefond1999} if:
\begin{enumerate}[label=\textup{(\roman*)}]
\item $\int_0^T\int_0^t K(t,s)^2\,ds\,dt < \infty$.
\item There exists $H \in (0,1)$ such that $|K(t,s)| \le C|t-s|^{H-1/2}$ for $s < t$.
\item $K$ has sufficient regularity for the Malliavin calculus: the fractional derivative $\partial_t K(t,s)$ exists and satisfies integrability conditions ensuring $\dom(\delta_X)$ is dense in $L^2(\Omega;\HX)$.
\end{enumerate}
\end{definition}

\begin{proposition}[Verification of framework axioms]\label{prop:volterra_verif}
Let $X$ be a Gaussian Volterra process with kernel~$K$ satisfying the Decreusefond--\"Ust\"unel conditions. Then the triple $(D_X, \delta_X, \Pi_X)$ satisfies:
\begin{enumerate}[label=\textup{(\alph*)}]
\item \textup{Chain rule:} $D_X(\varphi(F)) = \varphi'(F)\,D_XF$ for $F \in \mathcal{S}$, $\varphi \in C_b^1$.
\item \textup{Factorization:} $(\Id-\E)F = \delta_X(\Pi_X D_X F)$ for $F \in L^2(\Omega,{\FX}_T)$.
\item \textup{Orthogonal projection:} $\Pi_X$ is self-adjoint and idempotent in $L^2(\Omega;\HX)$.
\end{enumerate}
\end{proposition}

\begin{corollary}\label{cor:DX_process}
$D_XX_t = k_t$ for each $t \in [0,T]$: the operator derivative of the process at time~$t$ is the evaluation representer in the Cameron--Martin space.
\end{corollary}

\begin{definition}[Normalized Cameron--Martin space for fBM]\label{def:normalized_CM}
For fractional Brownian motion with $H \in (0,1)$, $H \neq 1/2$, we normalize the Cameron--Martin space $\HH$ so that the representer $k_t := D_H{\BH}_t$ satisfies
\begin{equation}\label{eq:normalization}
\|k_t\|^2_{\HH} = 2Ht^{2H-1}.
\end{equation}
This ensures $\int_0^t\|k_s\|^2_{\HH}\,ds = t^{2H}$, aligning with the classical Skorokhod integral formulas~\cite{Decreusefond1999,Nualart2006}.
\end{definition}

\begin{lemma}[Bracket for fBM]\label{lem:bracket_fbm}
With the normalization of Definition~\ref{def:normalized_CM}, for all $H \in (0,1)$, $H \neq 1/2$:
\[
\langle\BH\rangle_t^{(D,\Pi)} = t^{2H}.
\]
\end{lemma}

\begin{theorem}[Equivalences]\label{thm:equiv}
Let $\mathcal{D} \subset \dom(D_X)\cap L^4(\Omega)$ be a subalgebra stable under multiplication, dense in $\dom(D_X)$ under graph norm, and such that $F \in \mathcal{D}$ implies $F \in \mathbb{D}^{1,4}$ (i.e., $D_XF \in L^4(\Omega;\HX)$). Then the following are equivalent on~$\mathcal{D}$:
\begin{enumerate}[label=\textup{(\alph*)}]
\item \textup{Leibniz:} $D_X(FG) = FD_XG + GD_XF$.
\item \textup{Chain rule:} $D_X(f(F_1,\ldots,F_n)) = \sum_i\partial_if\cdot D_XF_i$ for $f \in C_b^\infty$.
\item \textup{Product rule for $\delta_X$:} $\delta_X(Fu) = F\delta_X(u) - \langle D_XF, u\rangle_{\HX}$.
\end{enumerate}
\end{theorem}

\begin{definition}[Cylindrical structure]\label{def:cyl}
$(\delta_X,\HX)$ admits a \emph{cylindrical structure} if there exist coordinates $(\xi_i)$ and representers $\kappa_i \in L^2(\Omega;\HX)$ such that $\mathcal{C} = \{f(\xi_1,\ldots,\xi_n) : f \in C_b^\infty\}$ is dense in $\dom(D_X)$ (graph norm) and satisfies the IBP:
\begin{equation}\label{eq:IBP_abstract}
\E[F\delta_X(u)] = \sum_{i=1}^n\E[\partial_if(\xi)\langle\kappa_i,u\rangle_{\HX}].
\end{equation}
Representers may be deterministic or random.
\end{definition}

\begin{theorem}[Cylindrical reduction]\label{thm:cylred}
Cylindrical structure implies: (a) $D_XF = \sum_i\partial_if(\xi)\kappa_i$ on $\mathcal{C}$; (b) Leibniz on $\mathcal{C}$; (c) Leibniz on $\mathbb{D}^{1,4}\cap L^4(\Omega)$, where $\mathbb{D}^{1,4} := \overline{\mathcal{C}}^{\|\cdot\|_{1,4}}$ with $\|F\|_{1,4}^4 := \E[|F|^4]+\E[\|D_XF\|^4_{\HX}]$.
\end{theorem}

\begin{theorem}[Leibniz for Gaussian Volterra]\label{thm:leib_gauss}
For a Gaussian Volterra process $X$ with Cameron--Martin space $\HX$, Leibniz holds on $\mathbb{D}^{1,4}(\Omega)$. (In the Gaussian setting, the Meyer inequalities ensure $\mathbb{D}^{1,4} = \mathbb{D}^{1,2}\cap L^4$, so this is equivalent to the natural domain.)
\end{theorem}

\begin{proposition}\label{prop:indep}
Isometry and Leibniz are logically independent conditions.
\end{proposition}

\begin{definition}[Intrinsic bracket]\label{def:bracket}
$\langle Y\rangle_t^{(D,\Pi)} := \int_0^t\|\Pi DY_s\|^2_{\mathcal{H}}\,ds$.
\end{definition}

\begin{definition}[$(D,\delta,\Pi)$-It\^o process]\label{def:ito_proc}
$Y$ is a $(D,\delta,\Pi)$-It\^o process if $Y$ is $L^2$-continuous, $Y_t \in \dom(D)$, and $Y_t = Y_0+\int_0^ta_s\,ds+\delta(\Pi DY\cdot\mathbf{1}_{[0,t]})$.
\end{definition}

\begin{lemma}[Product rule]\label{lem:prod_rule}
Under Leibniz, for $F \in \dom(D)\cap L^\infty$ and $u \in \dom(\delta)$ with $\|DF\|_{\mathcal{H}}\,\|u\|_{\mathcal{H}} \in L^2(\Omega)$ and $Fu \in \dom(\delta)$:
\begin{equation}\label{eq:prod_rule}
\delta(Fu) = F\delta(u) - \langle DF, u\rangle_{\mathcal{H}}.
\end{equation}
\end{lemma}

\begin{proposition}[Domain criterion for product rule]\label{prop:domain}
Let $F \in \dom(D)\cap L^\infty(\Omega)$ and $u \in \dom(\delta)$ with $\|DF\|_{\mathcal{H}}\,\|u\|_{\mathcal{H}} \in L^2(\Omega)$. Then $Fu \in \dom(\delta)$, and $\delta(Fu) = F\delta(u) - \langle DF, u\rangle_{\mathcal{H}}$.
\end{proposition}

\begin{lemma}[Orthogonal projection identity]\label{lem:orth}
$\Pi$ self-adjoint idempotent $\Rightarrow$ $\langle v, \Pi v\rangle = \|\Pi v\|^2$.
\end{lemma}

\begin{lemma}[Skorokhod isometry with remainder]\label{lem:skor_iso}
Let $(D,\delta,\Pi)$ satisfy the framework axioms and let $u \in \dom(\delta)$ be adapted ($\Pi u_s = u_s$ for a.e.~$s$) with $s \mapsto u_s$ H\"older continuous in $L^2(\Omega;\mathcal{H})$ with exponent $\gamma > 0$. Then for any interval $[t_k, t_{k+1}]$ with $\Delta t := t_{k+1}-t_k$:
\begin{equation}\label{eq:skor_iso}
\E\bigl[|\delta(u\cdot\mathbf{1}_{(t_k,t_{k+1}]})|^2\bigr] = \E\!\left[\int_{t_k}^{t_{k+1}}\|u_s\|^2_{\mathcal{H}}\,ds\right] + O((\Delta t)^{2\gamma+1}).
\end{equation}
\end{lemma}

\begin{theorem}[Operator It\^o formula (abstract scheme)]\label{thm:ito}
Let $(D,\delta,\Pi)$ satisfy the chain rule with $\Pi$ orthogonal, and assume the factorization $(\Id - \E)G = \delta(\Pi DG)$ holds for all $G$ in a class containing $\varphi(Y_t)$. Let $Y$ be a $(D,\delta,\Pi)$-It\^o process with $t\mapsto\Pi DY_t$ H\"older continuous in $L^2(\Omega;\mathcal{H})$, and assume:
\begin{enumerate}[label=\textup{(\roman*)}]
\item the Skorokhod isometry with remainder (Lemma~\ref{lem:skor_iso}) holds;
\item the stochastic Fubini interchange: for adapted $u \in \dom(\delta)$, $\int_0^t\delta(\Pi D(\varphi'(Y_s)a_s)\cdot\mathbf{1}_{[0,s]})\,ds$ can be expressed as a single divergence term that is absorbed by the product rule (Lemma~\ref{lem:prod_rule}).
\end{enumerate}
Then for $\varphi \in C_b^3(\R)$:
\begin{equation}\label{eq:ito}
\varphi(Y_t) = \varphi(Y_0)+\int_0^t\varphi'(Y_s)a_s\,ds+\delta(\varphi'(Y)\Pi DY\cdot\mathbf{1}_{[0,t]})+\frac{1}{2}\int_0^t\varphi''(Y_s)\|\Pi DY_s\|^2\,ds.
\end{equation}
\end{theorem}

\begin{theorem}[Multivariate extension]\label{thm:multi_ito}
Under the same assumptions as Theorem~\ref{thm:ito} applied componentwise (chain rule, factorization, Skorokhod isometry, and stochastic Fubini for each $Y^i$), let $Y = (Y^1,\ldots,Y^n)$ with each $Y^i$ a $(D,\delta,\Pi)$-It\^o process. Then for $\varphi \in C_b^3(\R^n)$:
\begin{align}
\varphi(Y_t) &= \varphi(Y_0)+\sum_i\int_0^t\partial_i\varphi(Y_s)a^i_s\,ds+\sum_i\delta(\partial_i\varphi(Y)\Pi DY^i\cdot\mathbf{1}_{[0,t]}) \notag\\
&\quad+\frac{1}{2}\sum_{i,j}\int_0^t\partial_i\partial_j\varphi(Y_s)\langle\Pi DY^i_s,\Pi DY^j_s\rangle_{\mathcal{H}}\,ds. \label{eq:multi_ito}
\end{align}
\end{theorem}

\begin{assumption}\label{ass:sv}
Let $W = (W_t)_{t \in [0,T]}$ be standard Brownian motion on $(\Omega, \mathcal{F}, P)$ and $\sigma = (\sigma_t)_{t \in [0,T]}$ a progressively measurable process satisfying:
\begin{enumerate}[label=(\roman*)]
\item \textup{Positivity:} $\sigma_t > 0$ a.s.\ for a.e.\ $t \in [0,T]$.
\item \textup{Square-integrability:} $\E[\int_0^T \sigma_t^2\,dt] < \infty$.
\item \textup{Malliavin differentiability:} $\sigma_t \in \mathbb{D}^{1,2}$ for a.e.~$t$, with $\E[\int_0^T \|D^W \sigma_t\|^2_{L^2[0,T]}\,dt] < \infty$.
\end{enumerate}
Define the continuous martingale $M_t := \int_0^t \sigma_s\,dW_s$.
\end{assumption}

\begin{definition}[Predictable energy space]\label{def:HM_pred}
$\HM^{\mathrm{pred}} := L^2([0,T] \times \Omega,\, \mathcal{P},\, d\langle M\rangle \otimes dP) = L^2([0,T] \times \Omega,\, \mathcal{P},\, \sigma_t^2\,dt \otimes dP)$. The stochastic integral is the It\^o integral: $\delta_M^{\mathrm{pred}}(u) = \int_0^T u_t\,dM_t = \int_0^T u_t \sigma_t\,dW_t$. This integral is isometric on $\HM^{\mathrm{pred}}$: $\E[|\delta_M^{\mathrm{pred}}(u)|^2] = \E[\int_0^T u_t^2 \sigma_t^2\,dt] = \|u\|^2_{\HM^{\mathrm{pred}}}$.
\end{definition}

\begin{proposition}[Explicit form of $D_M$]\label{prop:DM}
For $F \in \mathbb{D}^{1,2}$, the operator derivative on $\HM^{\mathrm{ext}}$ satisfies
\begin{equation}\label{eq:DM}
(D_M F)_t = \frac{D_t^W F}{\sigma_t} \qquad dt \otimes dP\text{-a.e.}
\end{equation}
\end{proposition}

\begin{theorem}[Leibniz for stochastic volatility]\label{thm:leib_sv}
Under Assumption~\ref{ass:sv}, $D_M$ on $\HM^{\mathrm{ext}}$ satisfies the Leibniz rule: for $F, G \in \mathbb{D}^{1,4}(\Omega)$,
\begin{equation}\label{eq:leib_sv}
D_M(FG) = F\,D_M G + G\,D_M F \qquad \text{in } L^2(\Omega; \HM^{\mathrm{ext}}).
\end{equation}
\end{theorem}

\begin{proposition}[Random cylindrical reduction]\label{prop:rand_cyl}
$(\delta_M^{\mathrm{ext}}, \HM^{\mathrm{ext}})$ satisfies the integration-by-parts formula~\eqref{eq:IBP_abstract} on smooth $M$-cylindricals $\mathcal{C}_M := \{f(M_{t_1},\ldots,M_{t_n}) : f \in C_b^\infty\}$ with random representers
\begin{equation}\label{eq:kappa}
\kappa_i(t) := \frac{D_t^W(M_{t_i})}{\sigma_t} = \mathbf{1}_{[0,t_i]}(t) + \frac{1}{\sigma_t}\int_t^{t_i} D_t^W(\sigma_s)\,dW_s.
\end{equation}
When $\sigma$ is deterministic, $D_t^W(\sigma_s) = 0$ for all $s$, so $\kappa_i(t) = \mathbf{1}_{[0,t_i]}(t)$: the standard deterministic representers.
\end{proposition}

\begin{theorem}[Obstruction]\label{thm:obstr}
Under Assumption~\ref{ass:sv}, suppose $(\delta_M^{\mathrm{ext}}, \HM^{\mathrm{ext}})$ admits a cylindrical structure (Definition~\ref{def:cyl}) with coordinates $\xi_i = M_{t_i}$ and \emph{deterministic} representers $\kappa_i$. Then $\sigma$ is deterministic, and consequently $\langle M\rangle_T = \int_0^T \sigma_t^2\,dt$ is deterministic.
\end{theorem}

\begin{conjecture}\label{conj:wild}
There exists a continuous process~$X$ with closed, centered stochastic integral such that the Leibniz defect $\Lambda(F,G) := D_X(FG) - F\,D_X G - G\,D_X F$ is nonzero and cannot be expressed as a polynomial in $F, G, D_X F, D_X G$. Candidates include continuous martingales on Tsirelson-type filtrations or processes whose quadratic variation is a singular function of time.
\end{conjecture}

\begin{lemma}[Uniform Mittag-Leffler bounds]
\label{lem:ml_bounds}
For every $\alpha \in (0, 2]$ there exists a
constant $C_\alpha > 0$ such that for all $r \geq 0$,
\begin{enumerate}[label=\textnormal{(\roman*)}]
\item $|E_\alpha(-r)| \leq 1$;
\item $|E_\alpha(-r)| \leq C_\alpha/(1 + r)$;
\item $|E_{\alpha,\alpha}(-r)| \leq C_\alpha/(1 + r)$.
\end{enumerate}
\end{lemma}

\begin{definition}[Resolvent family]\label{def:resolvent}
$\widehat{S_t^{(\alpha, H_1)} f}(\xi) = E_\alpha(-c_{H_1}|\xi|^{2H_1} t^\alpha)\,\hat{f}(\xi)$.
\end{definition}

\begin{lemma}[Resolvent properties]\label{lem:resolvent_props}
(a) $S_0 = I$. (b) $\norm{S_t f}_{L^2} \leq \norm{f}_{L^2}$. (c) $t \mapsto S_t f$ continuous. (d) $\partial_t^\alpha S_t f = A_{H_1} S_t f$ for $f \in \DD(A_{H_1}) := H^{2H_1}(\R)$.
\end{lemma}

\begin{definition}[Resolvent integrand]\label{def:resolvent_kernel}
$\widehat{\Phi_t}(\xi) := t^{\alpha-1} E_{\alpha,\alpha}(-c_{H_1}|\xi|^{2H_1} t^\alpha)$.
\end{definition}

\begin{definition}[Mild solution]\label{def:mild}
$X_t = S_t^{(\alpha, H_1)} f + \int_0^t \Phi_{t-s}\, dB_s$.
\end{definition}

\begin{corollary}[Cylindrical noise]
\label{thm:existence}
Let $\alpha = 2H_2$.  For $f \in L^2(\R)$,
$H_2 \in (1/4,1)$, and
$H_1 \in (\alpha/(2(2\alpha-1)),\ 1]$
(which forces $\alpha > 2/3$, equivalently
$H_2 > 1/3$), equation~\eqref{eq:quijotic_main}
with cylindrical Brownian noise ($Q = I$) admits a
unique mild solution.
\end{corollary}

\begin{theorem}\label{thm:continuity}
Under the assumptions of \Cref{thm:existence_trace}
or \Cref{thm:existence}, the mild solution satisfies
$X \in C([0,T]; L^2(\R))$ almost surely.
\end{theorem}

\begin{theorem}[Spectral decomposition]\label{thm:spectral}
The mild solution has Fourier representation
\begin{equation}\label{eq:spectral}
\hat{X}_t(\xi) = E_\alpha(-\lambda(\xi)\,t^\alpha)\,\hat{f}(\xi) + \int_0^t (t-s)^{\alpha-1} E_{\alpha,\alpha}(-\lambda(\xi)\,(t-s)^\alpha)\, d\hat{B}_s(\xi),
\end{equation}
where $\lambda(\xi) = c_{H_1}|\xi|^{2H_1}$ is the
mode-dependent decay rate and
$\hat{B}_t(\xi) := \int_\R e^{-i\xi x} dB_t(x)$
is the Fourier-space Brownian motion, satisfying
$\E[d\hat{B}_t(\xi)\,\overline{d\hat{B}_s(\eta)}]
= \delta(\xi - \eta)\,\delta(t-s)\,d\xi\,dt$.
\end{theorem}

\begin{corollary}[Mode-wise dynamics]\label{cor:modewise}
Each mode evolves as a scalar fractional OU: $\partial_t^\alpha \hat{X}_t(\xi) = -\lambda(\xi)\hat{X}_t(\xi) + d\hat{B}_t(\xi)/dt$. High-frequency modes decay rapidly; low-frequency modes persist.
\end{corollary}

\begin{corollary}[Mode-wise variance]\label{cor:mode_variance}
For $f = 0$: $\E[|\hat{X}_t(\xi)|^2] = \int_0^t s^{2(\alpha-1)} |E_{\alpha,\alpha}(-\lambda(\xi)s^\alpha)|^2\, ds$.
\end{corollary}

\begin{theorem}[Temporal H\"older continuity]\label{thm:temporal_reg}
$\E[\norm{X_t - X_s}_{L^2}^2] \leq C|t-s|^{2\beta}$ with $\beta = \min(2H_2, 1/2 - \varepsilon)$.
\end{theorem}

 egin{theorem}[Energy identity]\label{thm:energy}
$E(t) := \E[
orm{X_t}_{L^2}^2] = 
orm{S_t f}_{L^2}^2 + \int_0^t 
orm{\Phi_s}_{\mathrm{HS}}^2\, ds$.
\end{theorem}

\begin{proposition}[Energy bound]\label{prop:dissipation}
For the deterministic equation $\partial_t^\alpha u = A_{H_1} u$, the energy $e(t) = \norm{u_t}_{L^2}^2$ satisfies $e(t) \leq e(0)$ for all $t \geq 0$, and is monotonically nonincreasing when $\alpha \in (0, 1]$.
\end{proposition}

\begin{theorem}[Long-time decay]\label{thm:decay_det}
For $f \in L^1(\R) \cap L^2(\R)$ and $H_1 > 1/4$,
\begin{equation}\label{eq:decay}
\norm{S_t f}_{L^2} \leq C\,t^{-H_2/(2H_1)}
\norm{f}_{L^1} \qquad \text{as } t \to \infty.
\end{equation}
If additionally $\hat{f}(0) \neq 0$, the bound is
achieved: $\norm{S_t f}_{L^2} \geq c\,t^{-H_2/(2H_1)}$
for $t$ large.
\end{theorem}

\begin{theorem}[Stationary covariance, conditional]
\label{thm:stationary}
The stationary covariance
\[
Q_\infty := \int_0^\infty \Phi_s\, Q\, \Phi_s^*\, ds
\]
exists as a trace-class operator on $L^2(\R)$ provided
\begin{equation}\label{eq:stationary_HS}
\int_0^\infty \norm{\Phi_s Q^{1/2}}_{\mathrm{HS}}^2\, ds
< \infty.
\end{equation}
For $Q$ a Fourier multiplier of nonnegative symbol
$q(\xi)$, this is equivalent (up to constants) to the
low-frequency integrability condition
\begin{equation}\label{eq:stationary_lowfreq}
\int_\R q(\xi)\, \lambda(\xi)^{-(2\alpha-1)/\alpha}\, d\xi
< \infty,
\qquad \lambda(\xi) = c_{H_1}|\xi|^{2H_1}.
\end{equation}
\end{theorem}

\begin{proposition}[Variance scaling]\label{thm:selfsimilar}
Under the assumptions of \Cref{thm:existence_trace}
(trace-class noise) or \Cref{thm:existence}
(cylindrical noise with $H_1 > \alpha/(2(2\alpha-1))$),
for $f = 0$
and any $c > 0$, the variance scales as
\begin{equation}\label{eq:selfsimilar}
\E[\norm{X_{ct}}_{L^2}^2]
= c^{2H}\, \E[\norm{X_t}_{L^2}^2],
\qquad H = 2H_2 - \tfrac{1}{2} - \tfrac{H_2}{2H_1}.
\end{equation}
\end{proposition}

\begin{definition}[Operator derivative]
\label{def:D_quijotic}
$D := \delta^*$, defined by the adjoint identity:
for $F \in L^2(\Omega)$ and $u \in \HH_Q^t$,
\begin{equation}\label{eq:adjoint_identity}
\ip{DF}{u}_{\HH_Q^t} = \E[F \cdot \delta(u)].
\end{equation}
\end{definition}

\begin{theorem}[Exact representation]
\label{thm:clark_ocone}
In the Gaussian setting (noise $B$ is Brownian),
$D = \delta^*$ coincides with the Malliavin derivative,
the Leibniz rule holds (i.e., the Leibniz defect
$\Gamma(F,G) := D(FG) - F \cdot DG - G \cdot DF$
vanishes for all suitable $F, G$), and every
$F \in L^2(\FF_t)$ admits
\begin{equation}\label{eq:clark_ocone}
F - \E[F] = \int_0^t
\E[D_s F \mid \FF_s]\, dB_s.
\end{equation}
\end{theorem}

\begin{definition}[Leibniz defect]
\label{def:defect}
For $F, G \in \mathrm{dom}(D)$,
\begin{equation}\label{eq:defect}
\Gamma(F,G) := D(FG) - F \cdot DG - G \cdot DF.
\end{equation}
\end{definition}

\begin{proposition}[Defect propagation]
\label{prop:defect_propagation}
For the L\'evy fractional memory
process~\eqref{eq:levy_fmp}, a jump at time $s$
contributes to the defect at time $t > s$ with weight
\begin{equation}\label{eq:defect_weight}
|\widehat{\Phi_{t-s}}(\xi)|
\leq C\,(t-s)^{\alpha-1}
\cdot \frac{1}{1 + \lambda(\xi)(t-s)^\alpha}.
\end{equation}
For fixed $\xi$, this decays as $(t-s)^{\alpha-1}$
for small $t - s$ and as $(t-s)^{-1}$ for large
$t - s$---in both cases, polynomial.
\end{proposition}
